/// Two invariants the fast paths depend on, pinned so a new field turns a
/// silent regression into a build failure:
/// * keys are UNIQUE — `SettingsViewState::field_index` maps a key to one row,
///   and `unsaved_field_draft_count` counts keys rather than rows;
/// * keys and search keywords are ASCII-LOWERCASE — `field_match_score_in`
///   compares them against a lowercased query without folding them first, so a
///   capitalized key would become unsearchable.
#[test]
fn editable_field_keys_are_unique_and_lowercase() {
    let fields = prefs::editable_fields(&Config::default());
    let mut seen = BTreeSet::new();
    for field in &fields {
        assert!(
            seen.insert(field.key),
            "duplicate editable field {}",
            field.key
        );
        assert_eq!(
            field.key,
            field.key.to_ascii_lowercase(),
            "key must be lowercase"
        );
        for keyword in prefs::keywords_of(field.key) {
            assert_eq!(
                *keyword,
                keyword.to_ascii_lowercase(),
                "keyword of {} must be lowercase",
                field.key
            );
        }
    }
    let state = SettingsViewState::new(&Config::default());
    assert_eq!(
        state.field_index.len(),
        state.legacy.fields.len(),
        "the key index must cover every row"
    );
    for (position, field) in state.legacy.fields.iter().enumerate() {
        assert_eq!(state.field_index_of(field.key), Some(position));
    }
}

/// Depth-first lookup of one node by key, for the page-shape assertions
/// below (the Wallpaper card nests its controls under a `top_card`).
fn node_by_key<'a>(nodes: &'a [UiNode], key: &str) -> Option<&'a UiNode> {
    for node in nodes {
        if node.key.as_str() == key {
            return Some(node);
        }
        if let Some(found) = node_by_key(&node.children, key) {
            return Some(found);
        }
    }
    None
}

/// THE DEAD CLICK, pinned. "Choose Image…" carried no platform gate at all
/// while `menu::choose_local_file` was a `None` stub off macOS: it painted
/// enabled, took focus and hover, opened nothing, and left the status line
/// saying "No wallpaper" — the one place the Windows build broke the repo's
/// no-dead-click law.
///
/// The button's enabled state must now track the platform picker exactly, so
/// the row can never again claim an authority the process does not have. On
/// this machine (Windows, with a real `IFileOpenDialog`) that means ENABLED —
/// which is also the proof the ungating actually reached this surface.
#[test]
fn choose_image_is_enabled_exactly_when_a_picker_exists() {
    let state = SettingsViewState::new(&Config::default());
    let page = wallpaper_page(&state, SettingsWidth::Wide, view_cx().viewport);
    let choose =
        node_by_key(&page, "settings/wallpaper/choose").expect("the Wallpaper page offers it");
    let UiContent::Button(control) = &choose.content else {
        panic!("Choose Image… is a button control");
    };
    assert_eq!(control.spec.label, "Choose Image…");
    assert_eq!(
        control.state.enabled,
        crate::menu::local_file_picker_available(),
        "the button must be exactly as enabled as the platform picker is real"
    );
    #[cfg(any(target_os = "macos", windows))]
    assert!(
        control.state.enabled,
        "this platform HAS a picker, so the button must be live"
    );
}

/// Detach is gated on something else entirely (is a wallpaper attached?) and
/// must not have been swept up by the picker gate — the ungating brief is
/// "leave everything gated for other reasons alone".
#[test]
fn detach_stays_gated_on_an_attached_wallpaper_not_on_the_picker() {
    let state = SettingsViewState::new(&Config::default());
    let page = wallpaper_page(&state, SettingsWidth::Wide, view_cx().viewport);
    let detach =
        node_by_key(&page, "settings/wallpaper/detach").expect("the Wallpaper page offers it");
    let UiContent::Button(control) = &detach.content else {
        panic!("Detach is a button control");
    };
    assert!(
        !control.state.enabled,
        "a default config has no wallpaper, so there is nothing to detach"
    );
}

fn audited_availability() -> SettingsAvailability {
    SettingsAvailability {
        backend_gpu: true,
        macos: true,
        windows: false,
        notifications: true,
        trail_audio: true,
        packages: PackageAdmission::Ready,
        update_installable: true,
    }
}

fn test_patch(edits: &[(&str, &str)]) -> ConfigPatch {
    ConfigPatch {
        base_revision: 1,
        edits: edits
            .iter()
            .map(|(key, value)| ConfigEdit {
                key: (*key).to_string(),
                expected: ExpectedConfigValue::Exact(None),
                value: Some((*value).to_string()),
            })
            .collect(),
    }
}

fn projected_effect(
    source: &str,
    edits: &[(&str, &str)],
    key: &str,
    availability: SettingsAvailability,
    motion: crate::native_app::ViewMotionCx,
) -> SettingEffectProjection {
    let config: Config = aterm_toml::from_str(source).unwrap();
    let state = SettingsViewState::new(&config);
    let patch = test_patch(edits);
    setting_effect_projection(&state, Some(&patch), key, availability, motion)
}

fn effect_note_contains(effect: &SettingEffectProjection, expected: &str) -> bool {
    effect.notes.iter().any(|note| {
        note.semantic.contains(expected)
            || note.visual.contains(expected)
            || note.feedback.contains(expected)
    })
}

use crate::native_config_conformance::trail_pack_asset;

fn trail_pack_config(paths: &[String], style: &str) -> String {
    let paths = paths
        .iter()
        .map(|path| aterm_toml::Value::String(path.clone()).to_string())
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        "cursor_blink = false\ncursor_trail = true\ncursor_trail_style = {style:?}\ncursor_trail_packs = [{paths}]\n"
    )
}

fn authored_visual_state(key: &str, value: Option<&str>) -> SettingsViewState {
    // The comet-family trail knobs are inert under the additive default (its
    // typed wake is deliberately cadence-scaled in its signature spectrum
    // — duration/length/colour do not apply). Preview them under the
    // COMMITTED comet style whose engine honours them, on BOTH base and
    // candidate, so each knob's own effect is what the pixels prove.
    let config = if matches!(
        key,
        prefs::EDIT_CURSOR_TRAIL_MS
            | prefs::EDIT_CURSOR_TRAIL_LENGTH
            | prefs::EDIT_CURSOR_TRAIL_RADIUS
            | prefs::EDIT_CURSOR_TRAIL_RING
            | prefs::EDIT_CURSOR_TRAIL_COLOR
            | prefs::EDIT_CURSOR_TRAIL_ACCENT
    ) {
        Config {
            cursor_trail_style: Some("comet".to_string()),
            ..Config::default()
        }
    } else if key == prefs::EDIT_CURSOR_BLINK {
        // A caret that is typing, or that a rainbow body owns, holds steady
        // exactly as in a terminal; the blink shows on a resting caret: Off,
        // with the typing glow (which types even under Off) off too.
        Config {
            cursor_trail_style: Some("off".to_string()),
            cursor_momentum_glow: Some(false),
            ..Config::default()
        }
    } else if key == prefs::EDIT_CURSOR_MOMENTUM_GLOW {
        // The rainbow owns its caret and keeps the momentum glow off it.
        Config {
            cursor_trail: Some(true),
            cursor_trail_style: Some("lumen".to_string()),
            ..Config::default()
        }
    } else {
        Config::default()
    };
    // AND THE TRAIL-GATED ROWS GET THEIR MASTER. `TRAIL_TUNING_KEYS` is this
    // module's own list of rows the trail master gates — with it off they draw
    // nothing, so a candidate could only move the badge, never the specimen
    // body this fixture measures. The master's absent-key default is
    // platform-split (`app_config::DEFAULT_DECORATIVE_EFFECTS`), so authoring it
    // is what keeps the pixel matrix honest on Windows instead of pixel-blind.
    //
    // `cursor_trail` itself is excluded on purpose: there the master IS the
    // candidate, and its base must stay the platform default or the candidate
    // could not differ from it.
    let config = if key != prefs::EDIT_CURSOR_TRAIL
        && (TRAIL_TUNING_KEYS.contains(&key) || key == prefs::EDIT_CURSOR_TRAIL_STYLE)
    {
        Config {
            cursor_trail: Some(true),
            ..config
        }
    } else {
        config
    };
    let mut state = SettingsViewState::new(&config);
    state.route = preview_route_for_key(key).expect("visual route");
    state.common.last_focus = Some(UiKey::new(format!("settings/control/{key}")));
    if let Some(value) = value {
        state.editing_field = Some(key.to_string());
        state.field_inputs.insert(
            key.to_string(),
            crate::native_text_input::TextInputState::new(value.to_string()),
        );
    }
    state
}

fn compile_preview_for_pixels(
    spec: SettingsPreviewSpec,
) -> (crate::native_ui::CompiledUi, Vec<u8>) {
    let viewport = LogicalRect::new(0.0, 0.0, 520.0, 210.0);
    let tree = UiTree::new(
        UiNode::new(
            "root",
            UiContent::Group(GroupSpec::unlabeled(SemanticRole::Application)),
        )
        .layout(Layout::column().padding(Insets::all(8.0)))
        .children(vec![crate::settings_preview::preview_node(
            "preview", spec, 190.0,
        )]),
    );
    let compiled = tree.compile(viewport).expect("preview compiles");
    let prims = compiled.tray(aterm_render::Theme::default(), 13.0).prims;
    let pixels = crate::tray_raster::rasterize_tray(
        &prims,
        viewport.width as u32,
        viewport.height as u32,
        1.0,
        [0, 0, 0, 0],
    )
    .0;
    (compiled, pixels)
}

fn preview_body_pixels(compiled: &crate::native_ui::CompiledUi, pixels: &[u8]) -> Vec<u8> {
    const WIDTH: usize = 520;
    let rect = compiled
        .semantic(&UiKey::new("preview"))
        .expect("preview semantics")
        .rect;
    let x0 = (rect.x + 10.0).ceil().max(0.0) as usize;
    let x1 = (rect.right() - 10.0).floor().max(x0 as f32) as usize;
    // Paint's terminal canvas begins at header_h(27) + 5. Exclude one
    // additional AA row so the visible candidate badge cannot satisfy a
    // body-effect assertion.
    let y0 = (rect.y + 33.0).ceil().max(0.0) as usize;
    let y1 = (rect.bottom() - 10.0).floor().max(y0 as f32) as usize;
    let mut body = Vec::with_capacity((x1 - x0) * (y1 - y0) * 4);
    for row in y0..y1 {
        let start = (row * WIDTH + x0) * 4;
        let end = (row * WIDTH + x1) * 4;
        body.extend_from_slice(&pixels[start..end]);
    }
    body
}

#[test]
fn result_count_copy_uses_singular_and_plural_nouns() {
    // Nothing at all: the empty card says so, once.
    assert_eq!(settings_count_summary(0, 0, 0), None);
    assert_eq!(
        settings_count_summary(0, 0, 1).as_deref(),
        Some("1 key in aterm.toml")
    );
    assert_eq!(
        settings_count_summary(0, 0, 2).as_deref(),
        Some("2 keys in aterm.toml")
    );
    assert_eq!(
        settings_count_summary(1, 0, 3).as_deref(),
        Some("1 setting")
    );
    assert_eq!(
        settings_count_summary(2, 0, 0).as_deref(),
        Some("2 settings")
    );
    assert_eq!(settings_count_summary(0, 1, 0).as_deref(), Some("1 page"));
    assert_eq!(
        settings_count_summary(3, 2, 0).as_deref(),
        Some("2 pages · 3 settings")
    );
    assert_eq!(counted_value_label("entry", "entries", 0), "0 entries");
    assert_eq!(counted_value_label("entry", "entries", 1), "1 entry");
    assert_eq!(counted_value_label("entry", "entries", 2), "2 entries");
    assert_eq!(manual_override_preview("1", None), UNKNOWN_KEY_PREVIEW);
    assert_eq!(manual_override_preview("12", None), UNKNOWN_KEY_PREVIEW);
    assert_eq!(
        unknown_key_preview("scrollback_lnies"),
        "Unknown key · Did you mean scrollback_lines?"
    );
}

#[test]
fn every_visual_field_previews_candidate_semantics_fingerprint_pixels_and_isolation() {
    // The `window_theme` candidate must land on the side OPPOSITE the one
    // this fixture's Auto resolves to, or the sample titlebar cannot move.
    // Ask the painter's own resolver which side that is — a hand-kept
    // per-platform table restates a rule it does not own, and goes quietly
    // pixel-blind the day the rule changes (Linux Auto follows the host
    // TERMINAL theme, the other platforms the OS appearance, and both of
    // those answers moved during the 2026-08 window-chrome work).
    //
    // A dark OS throughout, so the unset theme draws the dark Default: the
    // SDR glow boost rolls itself off on a light background
    // (`sdr_glow_budget`), so its candidate is visible only on a dark one.
    let dark_os = crate::native_app::ViewMotionCx {
        system_dark: true,
        ..Default::default()
    };
    let auto_window_sample_light = renderer_preview_spec(
        &authored_visual_state(prefs::EDIT_WINDOW_THEME, None),
        720,
        dark_os,
        13.0,
        1.0,
    )
    .expect("base preview for window_theme")
    .window_sample_is_light(aterm_render::Theme::default());
    let window_theme_candidate = if auto_window_sample_light {
        "dark"
    } else {
        "light"
    };
    // Same rule, same reason, for the trail master: a candidate only moves
    // pixels if it lands on the side OPPOSITE the committed state, and the
    // committed state for an unwritten `cursor_trail` is the PLATFORM default
    // (`app_config::DEFAULT_DECORATIVE_EFFECTS`). A typed "false" would be a
    // no-op candidate on Windows and this fixture would go pixel-blind on
    // exactly the platform whose default just moved.
    const CURSOR_TRAIL_CANDIDATE: &str = if crate::app_config::DEFAULT_DECORATIVE_EFFECTS {
        "false"
    } else {
        "true"
    };
    let cases: [(&str, &str); 54] = [
        (prefs::EDIT_THEME, "Nord"),
        (prefs::EDIT_FOREGROUND, "#00FF66"),
        (prefs::EDIT_BACKGROUND, "#101820"),
        (prefs::EDIT_CURSOR_COLOR, "#FF00FF"),
        (prefs::EDIT_SELECTION_COLOR, "#335577"),
        (prefs::EDIT_SELECTION_FOREGROUND, "#00FF66"),
        (prefs::EDIT_WINDOW_THEME, window_theme_candidate),
        // 10, not 4.5: the default palette is deliberately lifted so every
        // ANSI token already reaches ~4.5:1 on the dark bg (see
        // `aterm_types::color_palette`) — a 4.5 floor is pixel-neutral by
        // design, while 10 provably floors the faint/red/blue specimens.
        (prefs::EDIT_MINIMUM_CONTRAST, "10"),
        (prefs::EDIT_SELECTION_INACTIVE, "true"),
        (prefs::EDIT_BOLD_IS_BRIGHT, "false"),
        (prefs::EDIT_FAINT_OPACITY, "0.8"),
        (prefs::EDIT_FONT_FAMILY, "JetBrains Mono"),
        (prefs::EDIT_FONT_PX, "20"),
        (prefs::EDIT_FONT_FAMILY_BOLD, "Fira Code"),
        (prefs::EDIT_FONT_FAMILY_ITALIC, "Iosevka"),
        (prefs::EDIT_FONT_FAMILY_BOLD_ITALIC, "Cascadia Code"),
        (prefs::EDIT_FONT_SYNTHETIC_STYLE, "false"),
        (
            prefs::EDIT_FALLBACK_FONTS,
            "DejaVu Sans Mono, Noto Sans CJK",
        ),
        (prefs::EDIT_SYMBOL_FONT, "Symbola"),
        (prefs::EDIT_EMOJI_FONT, "Apple Color Emoji"),
        (prefs::EDIT_LIGATURES, "false"),
        (prefs::EDIT_LINE_HEIGHT, "1.5"),
        (prefs::EDIT_ADJUST_BASELINE, "3"),
        (prefs::EDIT_ADJUST_UNDERLINE_POSITION, "2"),
        (prefs::EDIT_ADJUST_UNDERLINE_THICKNESS, "3"),
        (prefs::EDIT_UNDERLINE_SKIP_DESCENDERS, "false"),
        (prefs::EDIT_CURSOR_BREAK_LIGATURES, "true"),
        (prefs::EDIT_MERGED_LIGATURES, "true"),
        (prefs::EDIT_TEXT_BLENDING, "linear"),
        (prefs::EDIT_FONT_THICKEN, "true"),
        (prefs::EDIT_STEM_GAMMA, "0.7"),
        (prefs::EDIT_FONT_WEIGHT, "700"),
        (prefs::EDIT_FONT_VARIATION, "wdth=85, slnt=-8"),
        (prefs::EDIT_CURSOR_STYLE, "bar"),
        (prefs::EDIT_CURSOR_BLINK, "false"),
        (prefs::EDIT_CURSOR_MOMENTUM_GLOW, "false"),
        (prefs::EDIT_CURSOR_TRAIL, CURSOR_TRAIL_CANDIDATE),
        (prefs::EDIT_CURSOR_TRAIL_STYLE, "water"),
        (prefs::EDIT_CURSOR_TRAIL_MS, "900"),
        (prefs::EDIT_CURSOR_TRAIL_LENGTH, "48"),
        (prefs::EDIT_CURSOR_TRAIL_INTENSITY, "0.25"),
        (prefs::EDIT_CURSOR_TRAIL_RADIUS, "1.2"),
        (prefs::EDIT_CURSOR_TRAIL_RING, "false"),
        (prefs::EDIT_CURSOR_TRAIL_COLOR, "#FF5A7D"),
        (prefs::EDIT_CURSOR_TRAIL_ACCENT, "#00E5FF"),
        (prefs::EDIT_CURSOR_NYAN_SPRITE, "candidate-cat.png"),
        (prefs::EDIT_CURSOR_TRAIL_BLOOM, "false"),
        (prefs::EDIT_CURSOR_TRAIL_BLOOM_STRENGTH, "1.7"),
        (prefs::EDIT_CURSOR_TRAIL_BLOOM_RADIUS, "4.0"),
        (prefs::EDIT_CURSOR_FIRE_SHIMMER, "false"),
        (prefs::EDIT_HDR_GLOW, "false"),
        (prefs::EDIT_CURSOR_GLOW_SDR_BOOST, "0.8"),
        (prefs::EDIT_MOTION, "reduced"),
        (prefs::EDIT_LOAD_ADAPTIVE_MOTION, "false"),
    ];
    assert_eq!(
        cases.iter().map(|(key, _)| *key).collect::<BTreeSet<_>>(),
        prefs::VISUAL_PREVIEW_KEYS.iter().copied().collect(),
    );

    let mut renderer = aterm_render::Renderer::from_bytes(
        include_bytes!("../../aterm-render/tests/fixtures/jetbrains-mono.ttf"),
        14.0,
        aterm_render::Theme::default(),
    )
    .expect("embedded preview renderer");
    renderer.set_runtime_font_discovery(false);
    renderer.prepare_semantic_typography("Bold Italic != => 你好 ∑✓♥ 😀 🚀 👩‍💻");
    // SETTLED install: `set_chrome_fonts` would park an async prewarm
    // worker whose landing between two paints of one state could swap the
    // semantic cascade mid-assertion (cross-test flake under a parallel
    // suite run). The fixture warms the cascade inline instead.
    crate::tray_raster::install_settled_chrome_fonts_for_test(renderer);

    for (key, candidate_value) in cases {
        let base_state = authored_visual_state(key, None);
        let candidate_state = authored_visual_state(key, Some(candidate_value));
        let raw_before = candidate_state.raw_values.clone();
        let assets_before = Arc::clone(candidate_state.config_assets());
        // The frozen animation phase must make each candidate OBSERVABLE
        // (530ms blink half-periods): 720 is an ODD half-period, hiding a
        // blinking cursor — exactly what cursor_blink needs (hidden base vs
        // lit non-blinking candidate) — while cursor colour/style and the
        // cursor-anchored ligature break need an EVEN phase so the blinking
        // cursor is LIT in both frames.
        let phase_ms = if matches!(
            key,
            prefs::EDIT_CURSOR_COLOR
                | prefs::EDIT_CURSOR_STYLE
                | prefs::EDIT_CURSOR_BREAK_LIGATURES
        ) {
            480
        } else {
            720
        };
        let base = renderer_preview_spec(&base_state, phase_ms, dark_os, 13.0, 1.0)
            .unwrap_or_else(|| panic!("base preview for {key}"));
        let candidate = renderer_preview_spec(&candidate_state, phase_ms, dark_os, 13.0, 1.0)
            .unwrap_or_else(|| panic!("candidate preview for {key}"));
        let base_font = crate::tray_raster::prepare_semantic_font(&base.font_candidate);
        let candidate_font = if candidate.font_candidate == base.font_candidate {
            base_font.clone()
        } else {
            crate::tray_raster::prepare_semantic_font(&candidate.font_candidate)
        };
        let base = base.with_prepared_font(base_font);
        let candidate = candidate.with_prepared_font(candidate_font);
        assert!(
            candidate
                .audit_value()
                .contains(&format!("normalized-candidate {key}={candidate_value}")),
            "literal candidate semantics for {key}: {}",
            candidate.audit_value(),
        );
        assert_ne!(
            base.paint_fingerprint(),
            candidate.paint_fingerprint(),
            "{key}"
        );

        let (base_ui, base_pixels) = compile_preview_for_pixels(base);
        let (candidate_ui, candidate_pixels) = compile_preview_for_pixels(candidate);
        let base_semantic = base_ui
            .semantic(&UiKey::new("preview"))
            .expect("base preview semantics");
        let candidate_semantic = candidate_ui
            .semantic(&UiKey::new("preview"))
            .expect("candidate preview semantics");
        assert_eq!(
            base_semantic.rect, candidate_semantic.rect,
            "{key} geometry"
        );
        assert_eq!(base_ui.hits, candidate_ui.hits, "{key} hit geometry");
        assert_ne!(
            base_pixels, candidate_pixels,
            "{key} must change visible pixels"
        );
        // Body-observability exemptions — candidates the frozen specimen
        // CORRECTLY cannot show, which stay covered by the badge pixels,
        // semantics, and fingerprint asserted above:
        // - merged_ligatures (`admit_collapsed`) admits only the Cascadia
        //   N:1 collapsed-ligature convention; the deterministic JetBrains
        //   fixture (like DejaVu) uses the 1:1 spacer convention.
        // - trail length/radius/ring/accent decorate JUMP wakes (length
        //   caps a jump's swept path; radius/ring/accent shape the landing
        //   halo), while the preview's bounded script deliberately types
        //   single-cell moves only. Making these four body-observable
        //   requires scripting a jump into the preview motion.
        let body_exempt = matches!(
            key,
            prefs::EDIT_MERGED_LIGATURES
                | prefs::EDIT_CURSOR_TRAIL_LENGTH
                | prefs::EDIT_CURSOR_TRAIL_RADIUS
                | prefs::EDIT_CURSOR_TRAIL_RING
                | prefs::EDIT_CURSOR_TRAIL_ACCENT
        )
        // - font_thicken is CoreText FONT SMOOTHING at raster time;
        //   `Renderer::set_font_thicken` is a no-op beyond recording the
        //   flag anywhere fontdue rasterizes (no smoothing exists), and
        //   the Settings row discloses exactly that inertness. The badge
        //   pixels, semantics, and fingerprint above stay asserted.
        || (key == prefs::EDIT_FONT_THICKEN && !cfg!(target_os = "macos"));
        if !body_exempt {
            let base_body = preview_body_pixels(&base_ui, &base_pixels);
            let candidate_body = preview_body_pixels(&candidate_ui, &candidate_pixels);
            assert_ne!(
                base_body, candidate_body,
                "{key} must change the actual specimen body, not only its candidate badge",
            );
        }

        assert_eq!(
            candidate_state.raw_values, raw_before,
            "{key} config text isolation"
        );
        assert!(
            Arc::ptr_eq(candidate_state.config_assets(), &assets_before),
            "{key} asset identity"
        );
        assert!(
            candidate_state.pending.is_empty(),
            "{key} starts no config transaction"
        );
    }
}

#[test]
fn trail_pack_catalog_refreshes_for_new_snapshot_and_replacement() {
    let synthwave_path = trail_pack_asset("synthwave.toml");
    let emberfall_path = trail_pack_asset("emberfall.toml");
    let synthwave_text = trail_pack_config(std::slice::from_ref(&synthwave_path), "pack:synthwave");
    let synthwave_config: Config = aterm_toml::from_str(&synthwave_text).unwrap();

    let direct = SettingsViewState::new(&synthwave_config);
    assert!(
        direct.legacy.trail_pack_ids.is_empty(),
        "compatibility constructor stays manifest-IO-free"
    );

    let mut service = VersionedConfigService::new(synthwave_text).unwrap();
    let service_snapshot = service.snapshot();
    let synthwave_fp = service_snapshot
        .assets
        .trail_packs
        .get("synthwave")
        .expect("loaded synthwave")
        .pack_fp;
    assert_ne!(synthwave_fp, 0);

    let mut snapshot = SettingsViewState::from_snapshot(&service_snapshot).unwrap();
    assert_eq!(snapshot.legacy.trail_pack_ids, ["synthwave"]);
    assert_eq!(
        snapshot
            .trail_pack_catalog()
            .get("synthwave")
            .map(|pack| pack.pack_fp),
        Some(synthwave_fp)
    );

    let replacement = service
        .replace_external(trail_pack_config(
            std::slice::from_ref(&emberfall_path),
            "pack:emberfall",
        ))
        .unwrap();
    snapshot.replace_snapshot(&replacement).unwrap();
    assert_eq!(snapshot.legacy.trail_pack_ids, ["emberfall"]);
    assert!(
        !snapshot
            .trail_pack_catalog()
            .packs
            .contains_key("synthwave")
    );
    assert!(
        snapshot
            .trail_pack_catalog()
            .packs
            .contains_key("emberfall")
    );
}

// The fallback raw projection (`SettingsViewState::new` — the recovery/test
// path) must treat dotted keys exactly like the snapshot projection, at
// BOTH registered depths: a configured `[matrix_rain]`/`[packages]` bool
// and a configured `[sparkle_words.*]` sub-table bool are EXPLICIT
// (present in the Modified review; OCC expects `Exact(Some(..))`), an
// absent one is not.
#[test]
fn fallback_raw_projection_covers_dotted_keys() {
    let config: Config = aterm_toml::from_str(
        "[matrix_rain]\nenabled = true\n[packages]\nenabled = false\nauto_install = true\n\
         [update]\nenabled = false\n[reroute]\nannounce = false\n\
         [sparkle_words.profanity]\nenabled = false\n[sparkle_words.feline]\nenabled = true\n\
         [sparkle_words.ink]\nloop = true\n",
    )
    .unwrap();
    let state = SettingsViewState::new(&config);
    for (key, want) in [
        (prefs::EDIT_MATRIX_RAIN_ENABLED, "true"),
        (prefs::EDIT_PACKAGES_ENABLED, "false"),
        (prefs::EDIT_PACKAGES_AUTO_INSTALL, "true"),
        (prefs::EDIT_UPDATE_ENABLED, "false"),
        (prefs::EDIT_REROUTE_ANNOUNCE, "false"),
        ("sparkle_words.profanity.enabled", "false"),
        ("sparkle_words.feline.enabled", "true"),
        ("sparkle_words.ink.loop", "true"),
    ] {
        assert!(state.is_explicit(key), "{key} configured ⇒ explicit");
        assert_eq!(state.raw_value(key).as_deref(), Some(want), "{key}");
    }
    let absent = SettingsViewState::new(&Config::default());
    for key in [
        prefs::EDIT_MATRIX_RAIN_ENABLED,
        prefs::EDIT_PACKAGES_ENABLED,
        prefs::EDIT_PACKAGES_AUTO_INSTALL,
        prefs::EDIT_UPDATE_ENABLED,
        prefs::EDIT_REROUTE_ANNOUNCE,
        "sparkle_words.profanity.enabled",
        "sparkle_words.feline.enabled",
        "sparkle_words.ink.loop",
    ] {
        assert!(!absent.is_explicit(key), "{key} absent ⇒ not explicit");
    }
}

/// A carried draft is taken only by a row that takes TEXT — the rule
/// `field_accepts_text_input` states for `settings/set/`, focus, pointer
/// entry and `replace_snapshot` alike. The font-size row with a numeric
/// value is a SLIDER: `take_carried_field_drafts` used to take a draft for
/// it anyway (it excluded only switches, choices and themes), so the host
/// read the draft back as landed, said nothing, and the next config
/// snapshot discarded it (round three review).
#[test]
fn a_carried_draft_is_taken_only_by_a_row_that_takes_text() {
    let service = VersionedConfigService::new("font_px = 14\n".into()).unwrap();
    let mut state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    let slider = state
        .field_by_key(prefs::EDIT_FONT_PX)
        .expect("the font size row");
    assert!(
        numeric_slider_value(slider).is_some() && !field_accepts_text_input(slider),
        "PRECONDITION: the row is a slider, which takes no text"
    );
    state.take_carried_field_drafts(vec![
        crate::restore::SettingsDraftRestore {
            key: prefs::EDIT_FONT_FAMILY.to_string(),
            text: "Carried Mono".to_string(),
        },
        crate::restore::SettingsDraftRestore {
            key: prefs::EDIT_FONT_PX.to_string(),
            text: "17 px, maybe".to_string(),
        },
    ]);
    assert!(
        !state.field_inputs.contains_key(prefs::EDIT_FONT_PX),
        "the slider row takes no carried text: the host says it lost"
    );
    assert_eq!(
        state
            .field_inputs
            .get(prefs::EDIT_FONT_FAMILY)
            .map(crate::native_text_input::TextInputState::value),
        Some("Carried Mono"),
        "a text row takes its draft"
    );
}

// The production snapshot path for a DEPTH-2 leaf: a hand-set
// `sparkle_words.profanity.enabled` is explicit with its exact raw value
// (the full-depth dotted projection, not the whole-table opaque entry),
// and an absent one is not.
#[test]
fn snapshot_projection_covers_depth_two_dotted_keys() {
    let service =
        VersionedConfigService::new("[sparkle_words.profanity]\nenabled = false\n".into()).unwrap();
    let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    assert!(state.is_explicit("sparkle_words.profanity.enabled"));
    assert_eq!(
        state
            .raw_value("sparkle_words.profanity.enabled")
            .as_deref(),
        Some("false")
    );
    let absent = VersionedConfigService::new(String::new()).unwrap();
    let absent = SettingsViewState::from_snapshot(&absent.snapshot()).unwrap();
    assert!(!absent.is_explicit("sparkle_words.profanity.enabled"));
}

/// Loaded trail packs are styles too: each is a row of its own, after Off
/// and the built-in trails, named for its id where its manifest gives no
/// name (never "Trail pack ·" again under the TRAIL PACKS caption).
#[test]
fn cursor_styles_list_loaded_trail_packs_by_name() {
    let mut state = SettingsViewState::new(&Config::default());
    state.legacy.trail_pack_ids = vec!["synthwave".to_string(), "ember_fall".to_string()];
    let field = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
        .expect("trail style field");
    let choices = choices_for_field(field, &state.legacy.trail_pack_ids, &state.assets.themes)
        .expect("trail choices");
    assert_eq!(
        &choices[..prefs::CURSOR_TRAIL_STYLES.len()],
        prefs::CURSOR_TRAIL_STYLES
    );
    assert_eq!(
        &choices[prefs::CURSOR_TRAIL_STYLES.len()..],
        ["pack:ember_fall", "pack:synthwave"]
    );
    let listed = listed_cursor_styles(&state);
    let packs = listed
        .iter()
        .filter(|style| style.group == CursorStyleGroup::Packs)
        .map(|style| (style.value.as_str(), style.name.as_str()))
        .collect::<Vec<_>>();
    assert_eq!(
        packs,
        [
            ("pack:ember_fall", "Ember fall"),
            ("pack:synthwave", "Synthwave"),
        ]
    );
    let position = |value: &str| {
        listed
            .iter()
            .position(|style| style.value == value)
            .unwrap()
    };
    assert_eq!(position("off"), 0, "Off opens the list");
    assert!(position("classic") < position("pack:ember_fall"));
    assert_eq!(position("pack:synthwave"), listed.len() - 1);
}

/// THE PREVIEW'S COMPANION WEARS THE WINDOW'S CAT: the coat and eyes the
/// host says the cursor companion wears (`ViewMotionCx::companion_look`: the
/// favourite, the tenured program cat or the launch kitty) reach the cursor
/// preview, and a different cat repaints it rather than serving a stale
/// grey one from the raster memo.
#[test]
fn the_cursor_preview_wears_the_windows_companion_coat() {
    let state = SettingsViewState::new(&Config::default());
    let spec_for = |coat: u8, iris: u8| {
        let motion = crate::native_app::ViewMotionCx {
            companion_look: aterm_effects::kitty_registry::KittyLook {
                coat,
                iris,
                ..aterm_effects::kitty_registry::KittyLook::default()
            },
            ..crate::native_app::ViewMotionCx::default()
        };
        renderer_preview_spec_for_key_with_font(
            &state,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            0,
            motion,
            14.0,
            1.0,
            None,
        )
        .expect("a cursor preview")
    };
    let tan = spec_for(2, 1);
    assert_eq!(
        (
            tan.post_fx.companion_look.coat,
            tan.post_fx.companion_look.iris
        ),
        (2, 1)
    );
    assert_ne!(
        tan.paint_fingerprint(),
        spec_for(7, 3).paint_fingerprint(),
        "another cat repaints the preview"
    );
}

/// A LOADED PACK SAYS ITS OWN WORDS: its row takes the manifest's name and
/// description (Emberfall: "Warm red→gold beam shedding slow falling
/// embers."), each its own, never a shared filler line, and the saved pack's
/// Adjust card and the preview name it the same way.
#[test]
fn trail_pack_rows_use_their_manifests_name_and_description() {
    let paths = [
        trail_pack_asset("emberfall.toml"),
        trail_pack_asset("synthwave.toml"),
    ];
    let service = VersionedConfigService::new(trail_pack_config(&paths, "pack:emberfall")).unwrap();
    let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    let packs: Vec<(String, String)> = listed_cursor_styles(&state)
        .into_iter()
        .filter(|style| style.group == CursorStyleGroup::Packs)
        .map(|style| (style.name, style.description))
        .collect();
    assert_eq!(packs.len(), 2, "{packs:?}");
    assert_eq!(packs[0].0, "Emberfall");
    assert_eq!(
        packs[0].1,
        "Warm red\u{2192}gold beam shedding slow falling embers."
    );
    assert_eq!(packs[1].0, "Synthwave");
    assert_ne!(packs[0].1, packs[1].1, "each pack describes itself");
    assert_eq!(
        cursor_style_name_in("pack:emberfall", state.trail_pack_catalog()),
        "Emberfall"
    );
    // The cursor style's row on Top Settings, Search and Modified, and the
    // save's words, name it so too; a pack that is not loaded keeps saying
    // what it is.
    assert_eq!(
        setting_choice_label_in(&state, prefs::EDIT_CURSOR_TRAIL_STYLE, "pack:emberfall"),
        "Emberfall"
    );
    assert_eq!(
        setting_choice_label_in(&state, prefs::EDIT_CURSOR_TRAIL_STYLE, "pack:no_such"),
        "Trail pack \u{b7} No such"
    );
    let spec = renderer_preview_spec_for_key_with_font(
        &state,
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        0,
        crate::native_app::ViewMotionCx::default(),
        14.0,
        1.0,
        None,
    )
    .expect("a cursor preview");
    assert_eq!(spec.cursor.trail_style_label(), "Emberfall");
}

fn cursor_pack_punctuation_fixture() -> (aterm_tempfile::TempDir, String) {
    let dir = aterm_tempfile::tempdir().expect("private trail packs");
    let template = std::fs::read_to_string(trail_pack_asset("synthwave.toml"))
        .expect("the real trail pack fixture");
    let mut paths = Vec::new();
    for id in ["ember-fall", "ember_fall"] {
        let source = template.replace("id = \"synthwave\"", &format!("id = {id:?}"));
        let path = dir.path().join(format!("{id}.toml"));
        std::fs::write(&path, source).expect("write private trail pack");
        paths.push(path.to_str().expect("fixture path is UTF-8").to_string());
    }
    let source = trail_pack_config(&paths, "off");
    (dir, source)
}

/// Distinct valid IDs retain distinct controls after actual pack loading;
/// punctuation must not make a real Cursor Styles screen fail to compile.
#[test]
fn cursor_pack_punctuation_keeps_both_loaded_rows_renderable() {
    let (_dir, source) = cursor_pack_punctuation_fixture();
    let (runtime, instance, view) = cursor_styles_runtime(&source);
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.legacy.trail_pack_ids, ["ember-fall", "ember_fall"]);
    for id in ["ember-fall", "ember_fall"] {
        assert!(
            state.trail_pack_catalog().get(id).is_some(),
            "{id} compiled"
        );
    }
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(1_200.0, 2_000.0));
    let mut keys = BTreeSet::new();
    for id in ["ember-fall", "ember_fall"] {
        let key = UiKey::new(cursor_style_row_key(&format!("pack:{id}")));
        assert!(compiled.semantic(&key).is_some(), "{id} has its own row");
        assert!(keys.insert(key), "the two rows keep different identities");
    }
}

/// Activating either loaded pack's own row saves that exact pack, while an
/// ordinary built-in still follows the same action path.
#[test]
fn cursor_pack_punctuation_selects_the_exact_loaded_style() {
    let (_dir, source) = cursor_pack_punctuation_fixture();
    for wanted in ["pack:ember-fall", "pack:ember_fall", "water"] {
        let (mut runtime, instance, view) = cursor_styles_runtime(&source);
        let outcome = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(cursor_style_row_key(wanted)),
                    value: None,
                }),
            )
            .expect("activate the actual style row");
        let patches = config_patches(&outcome);
        assert_eq!(patches.len(), 1, "{wanted} starts one save");
        let edit = patches[0]
            .edits
            .iter()
            .find(|edit| edit.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
            .expect("the style is saved");
        assert_eq!(
            edit.value.as_deref(),
            Some(wanted),
            "save the selected style"
        );
    }
}

#[test]
fn native_theme_picker_keeps_builtins_first_and_adds_user_themes_once() {
    let choices = merge_theme_options([
        "My Solarized".to_string(),
        "dracula".to_string(),
        "Work Light".to_string(),
    ]);
    let builtins = aterm_types::scheme::builtin_names();
    assert_eq!(
        &choices[..builtins.len()],
        builtins.as_slice(),
        "the stable built-in registry remains the first picker section"
    );
    assert_eq!(
        &choices[builtins.len()..],
        ["My Solarized", "Work Light"],
        "user themes append in discovery order and cannot duplicate a built-in"
    );

    // A highlighted row previews through the one runtime resolver, from the
    // catalog this Settings generation carries: no per-row cache, no file read.
    let work_scheme = aterm_types::scheme::builtin("Dracula").unwrap();
    let custom =
        crate::app_config::ThemeCatalog::from_schemes([("Work".to_string(), work_scheme.clone())]);
    assert!(settings_theme_options(&custom).ends_with(&["Work".to_string()]));
    let mut state = settings_state_with_themes("", custom.clone());
    state.choice_picker = Some(ChoicePicker::for_themes(&custom, "Default", true, false));
    for (value, scheme) in [
        ("Nord", aterm_types::scheme::builtin("Nord").unwrap()),
        ("Work", work_scheme.clone()),
    ] {
        hover_theme_choice(&mut state, Some(value));
        assert_eq!(
            preview_terminal_theme(&state, true),
            PreviewTerminalTheme::from_scheme(&scheme),
            "hovering {value} previews its palette"
        );
    }
    // Picker and runtime share case-insensitive custom-theme identity.
    assert_eq!(
        preview_terminal_theme(
            &settings_state_with_themes("theme = \"work\"\n", custom),
            true
        ),
        PreviewTerminalTheme::from_scheme(&work_scheme),
    );
}

/// A Settings view over `source` whose catalog is `themes`.
fn settings_state_with_themes(
    source: &str,
    themes: Arc<crate::app_config::ThemeCatalog>,
) -> SettingsViewState {
    let config: Config = aterm_toml::from_str(source).unwrap();
    let mut assets = (*crate::app_config::ConfigAssetCatalog::empty()).clone();
    assets.themes = themes;
    SettingsViewState::from_config_and_assets(&config, Arc::new(assets))
}

/// Hover the open theme picker's row whose value is `value` (`None` is the
/// Reset row), scrolling it into view as a pointer user would.
fn hover_theme_choice(state: &mut SettingsViewState, value: Option<&str>) {
    let picker = state.choice_picker.as_ref().expect("theme picker");
    let index = picker
        .options
        .iter()
        .position(|option| option.value.as_deref() == value)
        .expect("theme row");
    picker.reveal(index);
    state.common.hovered = Some(UiKey::new(format!(
        "settings/choice/{}/{index}",
        prefs::EDIT_THEME
    )));
}

fn packed_ansi(scheme: &aterm_types::ColorScheme) -> [u32; 16] {
    PreviewTerminalTheme::from_scheme(scheme).ansi
}

#[test]
fn settings_preview_of_a_pristine_config_draws_the_default_scheme_ansi() {
    let pristine = settings_state_with_themes("", crate::app_config::ThemeCatalog::empty());
    let default_ansi = packed_ansi(&aterm_types::ColorScheme::default());
    // No theme previews the unset default's palette for the OS appearance
    // (Default, or Default Light), not a stand-in table.
    for (system_dark, name) in [(true, "Default"), (false, "Default Light")] {
        assert_eq!(
            preview_terminal_theme(&pristine, system_dark).ansi,
            packed_ansi(&aterm_types::scheme::builtin(name).unwrap()),
            "{name}"
        );
    }
    // Negative control: an explicit theme previews its own ANSI colours.
    let nord = settings_state_with_themes(
        "theme = \"Nord\"\n",
        crate::app_config::ThemeCatalog::empty(),
    );
    let nord_ansi = packed_ansi(&aterm_types::scheme::builtin("Nord").unwrap());
    assert_ne!(nord_ansi, default_ansi);
    assert_eq!(preview_terminal_theme(&nord, true).ansi, nord_ansi);
}

#[test]
fn settings_preview_applies_configured_and_drafted_palette_entries() {
    let configured = settings_state_with_themes(
        "theme = \"Nord\"\npalette = [\"#010203\", \"#A1B2C3\"]\n",
        crate::app_config::ThemeCatalog::empty(),
    );
    let mut expected = packed_ansi(&aterm_types::scheme::builtin("Nord").unwrap());
    expected[0] = 0x01_0203;
    expected[1] = 0xA1_B2C3;
    assert_eq!(preview_terminal_theme(&configured, true).ansi, expected);

    // A draft that has not been saved yet: `palette[1]` only.
    let mut drafted = settings_state_with_themes("", crate::app_config::ThemeCatalog::empty());
    let before = preview_terminal_theme(&drafted, true);
    drafted.field_inputs.insert(
        prefs::EDIT_PALETTE.to_string(),
        crate::native_text_input::TextInputState::new("#000000, #C0FFEE".to_string()),
    );
    let after = preview_terminal_theme(&drafted, true);
    assert_eq!(
        after.ansi[1], 0xC0_FFEE,
        "the drafted palette[1] is previewed"
    );
    assert_eq!(after.ansi[0], 0x00_0000);
    assert_eq!(
        after.ansi[2..],
        before.ansi[2..],
        "other slots keep the theme"
    );
    assert_ne!(
        before.ansi[1], 0xC0_FFEE,
        "negative control: the draft is what changed it"
    );
}

#[test]
fn settings_preview_selection_foreground_follows_the_theme_unless_configured() {
    let mut scheme = aterm_types::scheme::builtin("Nord").unwrap();
    scheme.selection_fg = Some(aterm_types::Rgb::new(0x12, 0x34, 0x56));
    let themes = crate::app_config::ThemeCatalog::from_schemes([("Marked".to_string(), scheme)]);
    let spec = |source: &str| {
        let mut state = settings_state_with_themes(source, themes.clone());
        state.route = SettingsRoute::Appearance;
        renderer_preview_spec(
            &state,
            0,
            crate::native_app::ViewMotionCx::default(),
            13.0,
            1.0,
        )
        .expect("appearance preview")
        .appearance
        .selection_foreground
    };
    assert_eq!(spec("theme = \"Marked\"\n"), Some(0x12_3456));
    assert_eq!(
        spec("theme = \"Marked\"\nselection_foreground = \"#ABCDEF\"\n"),
        Some(0xAB_CDEF),
        "config beats theme"
    );
    assert_eq!(
        spec(""),
        None,
        "Default sets none: the renderer's floor applies"
    );
}

#[test]
fn settings_preview_hovering_default_with_no_theme_set_changes_nothing() {
    let mut state = settings_state_with_themes(
        "foreground = \"#123456\"\n",
        crate::app_config::ThemeCatalog::empty(),
    );
    let before = preview_terminal_theme(&state, true);
    state.choice_picker = Some(ChoicePicker::for_themes(
        &state.assets.themes,
        "Default",
        true,
        false,
    ));
    hover_theme_choice(&mut state, Some("Default"));
    assert_eq!(preview_terminal_theme(&state, true), before);
    hover_theme_choice(&mut state, None);
    assert_eq!(preview_terminal_theme(&state, true), before, "Reset row");
    // Negative control: another row does change the preview.
    hover_theme_choice(&mut state, Some("Nord"));
    assert_ne!(preview_terminal_theme(&state, true), before);
}

/// With no theme set on a light OS the preview draws Default Light, the
/// reset row previews that same unset value, and the Default row pins the
/// dark Default (negative control: it changes the preview).
#[test]
fn settings_preview_unset_theme_on_a_light_os_is_default_light() {
    let mut state = settings_state_with_themes("", crate::app_config::ThemeCatalog::empty());
    let before = preview_terminal_theme(&state, false);
    let default_light = aterm_types::scheme::builtin("Default Light").unwrap();
    assert_eq!(
        before.bg,
        PreviewTerminalTheme::from_scheme(&default_light).bg,
        "an unset theme on a light OS draws Default Light"
    );
    state.choice_picker = Some(ChoicePicker::for_themes(
        &state.assets.themes,
        crate::app_config::UNSET_THEME,
        true,
        false,
    ));
    hover_theme_choice(&mut state, None);
    assert_eq!(preview_terminal_theme(&state, false), before, "Reset row");
    hover_theme_choice(&mut state, Some("Default"));
    assert_ne!(preview_terminal_theme(&state, false), before);
}

#[test]
fn split_theme_preview_follows_os_appearance_not_overridden_background_luminance() {
    let service = VersionedConfigService::new(
        "theme = \"dark:Dracula,light:GitHub Light\"\nbackground = \"#000000\"\n".to_string(),
    )
    .unwrap();
    let state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    let light = preview_terminal_theme(&state, false);
    let dark = preview_terminal_theme(&state, true);
    let expected_light =
        PreviewTerminalTheme::from_scheme(&aterm_types::scheme::builtin("GitHub Light").unwrap());
    let expected_dark =
        PreviewTerminalTheme::from_scheme(&aterm_types::scheme::builtin("Dracula").unwrap());

    assert_eq!(light.fg, expected_light.fg);
    assert_eq!(light.ansi, expected_light.ansi);
    assert_eq!(dark.fg, expected_dark.fg);
    assert_eq!(dark.ansi, expected_dark.ansi);
    assert_eq!(light.bg, 0x000000, "authored slot overrides still win");
    assert_eq!(dark.bg, 0x000000, "authored slot overrides still win");
}

#[test]
fn theme_projection_and_preview_share_catalog_split_and_default_fallback_semantics() {
    let state_with_themes = settings_state_with_themes;
    let project = |state: &SettingsViewState| {
        setting_effect_projection(
            state,
            None,
            prefs::EDIT_THEME,
            audited_availability(),
            crate::native_app::ViewMotionCx::default(),
        )
    };
    let default = PreviewTerminalTheme::from_scheme(&aterm_types::ColorScheme::default());

    let builtin = state_with_themes(
        "theme = \"Nord\"\n",
        crate::app_config::ThemeCatalog::empty(),
    );
    assert_eq!(
        preview_terminal_theme(&builtin, false),
        PreviewTerminalTheme::from_scheme(
            &aterm_types::scheme::builtin("Nord").expect("built-in Nord")
        )
    );
    assert!(!effect_note_contains(&project(&builtin), "unavailable"));

    let missing = state_with_themes(
        "theme = \"Office Missing\"\n",
        crate::app_config::ThemeCatalog::empty(),
    );
    assert_eq!(preview_terminal_theme(&missing, false), default);
    assert!(effect_note_contains(&project(&missing), "Default fallback"));

    let split_missing = state_with_themes(
        "theme = \"dark:Dracula,light:Office Missing\"\n",
        crate::app_config::ThemeCatalog::empty(),
    );
    assert_eq!(
        preview_terminal_theme(&split_missing, true),
        PreviewTerminalTheme::from_scheme(
            &aterm_types::scheme::builtin("Dracula").expect("built-in Dracula")
        )
    );
    assert_eq!(preview_terminal_theme(&split_missing, false), default);
    let split_note = project(&split_missing);
    assert!(effect_note_contains(
        &split_note,
        "light \"Office Missing\""
    ));
    assert!(effect_note_contains(&split_note, "Default fallback"));

    let omitted_light = state_with_themes(
        "theme = \"dark:Dracula\"\n",
        crate::app_config::ThemeCatalog::empty(),
    );
    let dracula = PreviewTerminalTheme::from_scheme(
        &aterm_types::scheme::builtin("Dracula").expect("built-in Dracula"),
    );
    // The omitted light side draws the side the value names, as the runtime does.
    assert_eq!(preview_terminal_theme(&omitted_light, false), dracula);
    assert_eq!(preview_terminal_theme(&omitted_light, true), dracula);
    assert!(
        project(&omitted_light).notes.is_empty(),
        "an intentionally omitted side is not an unavailable theme"
    );

    let invalid_split = state_with_themes(
        "theme = \"dark:Dracula,night:Nord\"\n",
        crate::app_config::ThemeCatalog::empty(),
    );
    assert_eq!(preview_terminal_theme(&invalid_split, true), dracula);
    assert_eq!(preview_terminal_theme(&invalid_split, false), dracula);
    let invalid_projection = project(&invalid_split);
    assert!(effect_note_contains(
        &invalid_projection,
        "Invalid theme selector"
    ));
    assert!(effect_note_contains(
        &invalid_projection,
        "Dark (Dracula) still applies"
    ));
    assert!(invalid_projection.has_live_effect);

    let work_scheme = aterm_types::scheme::builtin("GitHub Light").unwrap();
    let custom = state_with_themes(
        "theme = \"Work\"\n",
        crate::app_config::ThemeCatalog::from_schemes([("Work".to_string(), work_scheme.clone())]),
    );
    assert_eq!(
        preview_terminal_theme(&custom, false),
        PreviewTerminalTheme::from_scheme(&work_scheme)
    );
    assert!(project(&custom).notes.is_empty());
}

/// With no theme authored the preview paints Default's real palette (on a
/// dark OS), never a neon xterm table, and authored `palette` entries layer
/// over it by index as the terminal applies them.
#[test]
fn resting_preview_palette_is_the_default_theme_with_authored_palette_entries() {
    let default = PreviewTerminalTheme::from_scheme(&aterm_types::ColorScheme::default());
    let resting = preview_terminal_theme(&SettingsViewState::new(&Config::default()), true);
    assert_eq!(resting, default);
    assert_eq!(
        resting.ansi[9], 0x00FF_6E67,
        "Default's bright red, not #FF0000"
    );

    let config: Config =
        aterm_toml::from_str("palette = [\"#123456\", \"nope\", \"#ABCDEF\"]\n").unwrap();
    let palette = preview_terminal_theme(&SettingsViewState::new(&config), true);
    assert_eq!(palette.ansi[0], 0x0012_3456);
    assert_eq!(
        palette.ansi[1], default.ansi[1],
        "an unreadable entry keeps its slot"
    );
    assert_eq!(palette.ansi[2], 0x00AB_CDEF);
    assert_eq!(palette.ansi[3..], default.ansi[3..]);
}

/// A search preview demonstrates a setting the results show: never a hidden
/// row or a Manual-only key, and never a focused control outside the results.
#[test]
fn search_previews_only_a_visible_matching_setting() {
    let mut state = SettingsViewState::new(&Config::default());
    state.search = "columns".to_string();
    assert_eq!(focused_preview_key(&state), None, "Manual-only results");
    state.search = "trail".to_string();
    assert_ne!(
        focused_preview_key(&state).as_deref(),
        Some(prefs::EDIT_CURSOR_TRAIL),
        "the hidden effects master is never the preview"
    );
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_CURSOR_STYLE
    )));
    state.search = "columns".to_string();
    assert_eq!(
        focused_preview_key(&state),
        None,
        "focus outside the results"
    );
    state.search = "ligature".to_string();
    assert!(
        focused_preview_key(&state).is_some_and(|key| key.contains("ligature")),
        "a matching text setting previews"
    );
}

#[test]
fn highlighted_uncommitted_trail_pack_is_the_live_preview_candidate() {
    let synthwave_path = trail_pack_asset("synthwave.toml");
    let service = VersionedConfigService::new(trail_pack_config(
        std::slice::from_ref(&synthwave_path),
        "phaser",
    ))
    .unwrap();
    let mut state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
    state.navigate(SettingsRoute::CursorMotion);
    let motion = crate::native_app::ViewMotionCx::default();
    let before = renderer_preview_spec(&state, 900, motion, 13.0, 1.0).expect("committed preview");

    let field = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_CURSOR_TRAIL_STYLE)
        .expect("trail style field");
    let picker = ChoicePicker::new(
        prefs::EDIT_CURSOR_TRAIL_STYLE,
        choices_for_field(field, &state.legacy.trail_pack_ids, &state.assets.themes)
            .expect("trail choices"),
        SettingsState::display_value(field),
        state.is_explicit(prefs::EDIT_CURSOR_TRAIL_STYLE),
        field.seed.is_some(),
        &effective_default_for_field(prefs::EDIT_CURSOR_TRAIL_STYLE),
    );
    let pack_index = picker
        .options
        .iter()
        .position(|option| option.value.as_deref() == Some("pack:synthwave"))
        .expect("pack option");
    state.choice_picker = Some(picker);
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/choice/{}/{pack_index}",
        prefs::EDIT_CURSOR_TRAIL_STYLE
    )));

    let candidate =
        renderer_preview_spec(&state, 900, motion, 13.0, 1.0).expect("candidate preview");
    assert_eq!(candidate.cursor.trail_style, PreviewTrailStyle::Custom);
    assert_eq!(
        candidate
            .cursor
            .trail_pack
            .as_ref()
            .map(|pack| pack.pack_fp),
        state
            .trail_pack_catalog()
            .get("synthwave")
            .map(|pack| pack.pack_fp)
    );
    assert_eq!(candidate.animation(), PreviewAnimation::Continuous);
    assert!(
        candidate
            .audit_value()
            .contains("Trail Pack interpreter is live")
    );
    assert_ne!(before.paint_fingerprint(), candidate.paint_fingerprint());
    assert_eq!(
        state.raw_value(prefs::EDIT_CURSOR_TRAIL_STYLE).as_deref(),
        Some("phaser"),
        "moving picker focus previews without persisting"
    );
}

#[test]
fn renderer_preview_carries_rainbow_variant_identity_from_config() {
    use crate::settings_preview::PreviewTrailCompanion;
    use aterm_effects::kitty_pet::PetSpecies;

    let motion = crate::native_app::ViewMotionCx::default();
    for (raw, expected) in [
        // The underline spelling is a GEOMETRY of the kitty family and
        // draws the family's companion. It used to answer FlyingKitty here
        // — not by any rule, but because `style_names_kitty_pet` is a
        // whole-string equality that it happened not to match, so appending
        // one geometry word to `rainbow kitty` swapped the animal.
        (
            "rainbow kitty underline",
            PreviewTrailCompanion::Pet(PetSpecies::Cat),
        ),
        // `… tall` is the sibling spelling, and it draws the sibling's
        // ANIMAL: the word names the geometry the default already draws,
        // so it can no more swap the companion than `underline` can.
        (
            "rainbow kitty tall",
            PreviewTrailCompanion::Pet(PetSpecies::Cat),
        ),
        (
            "rainbow kitty pet",
            PreviewTrailCompanion::Pet(PetSpecies::Cat),
        ),
        (
            "rainbow dog pet",
            PreviewTrailCompanion::Pet(PetSpecies::Dog),
        ),
        ("rainbow kitty flying", PreviewTrailCompanion::FlyingKitty),
    ] {
        let config: Config = aterm_toml::from_str(&format!(
            "cursor_trail = true\ncursor_trail_style = {raw:?}\n"
        ))
        .unwrap();
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::CursorMotion);
        let preview = renderer_preview_spec(&state, 900, motion, 13.0, 1.0)
            .unwrap_or_else(|| panic!("preview for {raw}"));

        assert_eq!(preview.cursor.trail_style, PreviewTrailStyle::RainbowKitty);
        // The preview names the style by its listed spelling: `… tall` is a
        // spelling of the default.
        assert_eq!(
            preview.cursor.effective_trail_style_raw(),
            prefs::cursor_trail_style_canonical(raw).unwrap()
        );
        assert_eq!(preview.cursor.trail_companion(), expected, "{raw}");
    }
}

#[test]
fn preview_activity_comes_from_the_exact_authored_spec() {
    // The runway ANIMATES because the trail draws on it; the master is asked
    // for rather than inherited, because its absent-key default is
    // platform-split (`app_config::DEFAULT_DECORATIVE_EFFECTS`) and this test
    // is about the preview's activity resolution, not about the default.
    let mut home = SettingsViewState::new(&Config {
        cursor_trail: Some(true),
        ..Config::default()
    });
    let motion = crate::native_app::ViewMotionCx::default();
    assert_eq!(
        home.preview_animation(
            100,
            motion,
            13.0,
            1.0,
            LogicalRect::new(0.0, 0.0, 1_200.0, 720.0),
        ),
        PreviewAnimation::Continuous,
        "wide Top Settings animates its visible cursor runway without requiring focus"
    );
    assert_eq!(
        home.preview_animation(
            100,
            motion,
            13.0,
            1.0,
            LogicalRect::new(0.0, 0.0, 390.0, 568.0),
        ),
        PreviewAnimation::None,
        "compact Top Settings page 0 renders only a static theme sample"
    );
    // Once the compact list shows the trail card, its preview animates.
    home.page_reveal = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_CURSOR_TRAIL_STYLE
    )));
    let _ = settings_route_at(&home, &view_cx_at(390.0, 568.0));
    assert_eq!(
        home.preview_animation(
            100,
            motion,
            13.0,
            1.0,
            LogicalRect::new(0.0, 0.0, 390.0, 568.0),
        ),
        PreviewAnimation::Continuous,
        "the visible cursor-trail card keeps its live preview"
    );

    let mut appearance = SettingsViewState::new(&Config::default());
    appearance.navigate(SettingsRoute::Appearance);
    assert_eq!(
        appearance.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport),
        PreviewAnimation::None,
        "Appearance is a genuinely static renderer sample"
    );
    assert!(
        renderer_preview_spec(&appearance, 100, motion, 17.5, 1.0)
            .unwrap()
            .audit_value()
            .contains("17.5 px"),
        "an unset font-size preview uses the renderer's applied size"
    );
    assert!(
        renderer_preview_spec(&appearance, 100, motion, 1.0, 1.0)
            .unwrap()
            .audit_value()
            .contains("6 px"),
        "host font fallback is normalized to the prefs minimum"
    );

    for (authored, expected) in [
        ("BAR", PreviewCursorStyle::Bar),
        (" Beam ", PreviewCursorStyle::Bar),
        ("Underline", PreviewCursorStyle::Bar),
        ("hidden", PreviewCursorStyle::Block),
    ] {
        let config: Config = aterm_toml::from_str(&format!(
            "cursor_style = {authored:?}\ncursor_blink = false\ncursor_trail = false\n"
        ))
        .unwrap();
        let mut state = SettingsViewState::new(&config);
        state.navigate(SettingsRoute::CursorMotion);
        assert_eq!(
            renderer_preview_spec(&state, 100, motion, 13.0, 1.0)
                .unwrap()
                .cursor
                .style,
            expected,
            "cursor preview must share the owning resolver for {authored:?}"
        );
    }

    let hidden: Config = aterm_toml::from_str(
        "cursor_style = \"hidden\"\ncursor_blink = true\ncursor_trail = false\n",
    )
    .unwrap();
    let mut hidden = SettingsViewState::new(&hidden);
    hidden.navigate(SettingsRoute::CursorMotion);
    assert_eq!(
        hidden.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport),
        PreviewAnimation::BlinkEdge { after_ms: 430 },
        "an unknown configured cursor style falls back to the runtime's blinking Block"
    );

    let blink: Config = aterm_toml::from_str(
        "cursor_style = \"block\"\ncursor_blink = true\ncursor_trail = false\n",
    )
    .unwrap();
    let mut blink = SettingsViewState::new(&blink);
    blink.navigate(SettingsRoute::CursorMotion);
    assert_eq!(
        blink.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport),
        PreviewAnimation::BlinkEdge { after_ms: 430 }
    );

    let zero: Config = aterm_toml::from_str(
        "cursor_blink = false\ncursor_trail = true\ncursor_trail_style = \"phaser\"\ncursor_trail_intensity = 0.0\ncursor_momentum_glow = false\n",
    )
    .unwrap();
    let mut zero = SettingsViewState::new(&zero);
    zero.navigate(SettingsRoute::CursorMotion);
    assert_eq!(
        zero.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport),
        PreviewAnimation::None,
        "a zero-intensity trail does not arm invisible work"
    );
    // The typing glow is its own visible work at any trail intensity, as in
    // a terminal, so it types.
    let glowing: Config = aterm_toml::from_str(
        "cursor_blink = false\ncursor_trail = true\ncursor_trail_style = \"phaser\"\ncursor_trail_intensity = 0.0\n",
    )
    .unwrap();
    let mut glowing = SettingsViewState::new(&glowing);
    glowing.navigate(SettingsRoute::CursorMotion);
    assert_eq!(
        glowing.preview_animation(100, motion, 13.0, 1.0, view_cx().viewport),
        PreviewAnimation::Continuous
    );
}

#[test]
fn canonical_non_cursor_previews_are_pixel_static_across_live_blink_edges() {
    crate::tray_raster::prepare_ui_fonts_for_direct_view_test();
    let config: Config = aterm_toml::from_str(
        "cursor_style = \"bar\"\ncursor_blink = true\ncursor_trail = true\ncursor_trail_style = \"phaser\"\n",
    )
    .unwrap();
    let motion = crate::native_app::ViewMotionCx::default();

    for route in [SettingsRoute::Appearance, SettingsRoute::TextFonts] {
        let mut state = SettingsViewState::new(&config);
        state.navigate(route);
        let early = renderer_preview_spec(&state, 100, motion, 13.0, 1.0)
            .unwrap_or_else(|| panic!("early {route:?} preview"));
        let late = renderer_preview_spec(&state, 600, motion, 13.0, 1.0)
            .unwrap_or_else(|| panic!("late {route:?} preview"));

        assert_eq!(early.animation(), PreviewAnimation::None, "{route:?}");
        assert_eq!(late.animation(), PreviewAnimation::None, "{route:?}");
        assert!(!early.cursor.blink, "{route:?} keeps its static cursor");
        assert!(
            !early.cursor.trail_enabled,
            "{route:?} keeps cursor motion out of its scene"
        );
        assert_eq!(
            early.paint_fingerprint(),
            late.paint_fingerprint(),
            "{route:?} retained identity is phase-static"
        );
        assert_eq!(
            compile_preview_for_pixels(early).1,
            compile_preview_for_pixels(late).1,
            "{route:?} pixels are phase-static"
        );
    }
}

#[test]
fn serious_mode_suppresses_native_preview_trails_post_fx_and_cadence() {
    let config: Config = aterm_toml::from_str(
        "cursor_blink = true\n\
         cursor_trail = true\n\
         cursor_trail_style = \"fire\"\n\
         cursor_trail_bloom = true\n\
         cursor_fire_shimmer = true\n\
         hdr_glow = true\n\
         cursor_glow_sdr_boost = 0.5\n",
    )
    .unwrap();
    let mut state = SettingsViewState::new(&config);
    state.navigate(SettingsRoute::CursorMotion);
    state.common.last_focus = Some(UiKey::new(format!(
        "settings/control/{}",
        prefs::EDIT_CURSOR_FIRE_SHIMMER
    )));

    let active = renderer_preview_spec(
        &state,
        100,
        crate::native_app::ViewMotionCx::default(),
        13.0,
        1.0,
    )
    .expect("active cursor preview");
    assert!(
        active.cursor.trail_enabled,
        "negative control: trail is authored"
    );
    assert!(active.post_fx.bloom, "negative control: bloom is authored");
    assert!(
        active.post_fx.fire_shimmer,
        "negative control: fire shimmer is authored"
    );

    let serious_motion = crate::native_app::ViewMotionCx {
        serious: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    let serious = renderer_preview_spec(&state, 100, serious_motion, 13.0, 1.0)
        .expect("serious cursor preview remains available");
    assert!(serious.reduced_motion);
    assert!(!serious.cursor.trail_enabled);
    assert!(!serious.post_fx.bloom);
    assert!(!serious.post_fx.fire_shimmer);
    assert!(!serious.post_fx.hdr_glow);
    assert_eq!(serious.post_fx.sdr_boost, 0.0);
    assert_eq!(serious.animation(), PreviewAnimation::None);
    assert_ne!(active.paint_fingerprint(), serious.paint_fingerprint());
}

#[test]
fn serious_mode_style_candidate_previews_the_atomic_post_commit_state() {
    let config: Config = aterm_toml::from_str(
        "serious_mode = true\ncursor_trail = true\ncursor_trail_style = \"fire\"\n",
    )
    .unwrap();
    let mut state = SettingsViewState::new(&config);
    state.navigate(SettingsRoute::CursorStyles);
    let serious = crate::native_app::ViewMotionCx {
        serious: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    let preview = |state: &SettingsViewState| {
        renderer_preview_spec_for_key_with_font(
            state,
            prefs::EDIT_CURSOR_TRAIL_STYLE,
            100,
            serious,
            13.0,
            1.0,
            None,
        )
        .unwrap()
    };

    // Nothing tried: the preview reads what Serious Mode draws, no trail.
    let resting = preview(&state);
    assert!(!resting.cursor.trail_enabled);
    assert_eq!(resting.focused_value, "off");

    state.common.last_focus = Some(UiKey::new(cursor_style_row_key("water")));
    let focused = preview(&state);
    assert!(focused.cursor.trail_enabled);
    assert!(!focused.reduced_motion);
    assert_eq!(focused.cursor.trail_style, PreviewTrailStyle::Water);
    assert!(focused.post_fx.motion_reason.contains("post-commit"));

    state.common.last_focus = None;
    state.common.hovered = Some(UiKey::new(cursor_style_row_key("water")));
    let hovered = preview(&state);
    assert!(hovered.cursor.trail_enabled);
    assert_eq!(hovered.cursor.trail_style, PreviewTrailStyle::Water);

    state.common.hovered = Some(UiKey::new(cursor_style_row_key("off")));
    let off_candidate = preview(&state);
    assert!(!off_candidate.cursor.trail_enabled);
    assert!(off_candidate.reduced_motion);
    assert!(field_bool(&state, prefs::EDIT_SERIOUS_MODE, false));
}

#[test]
fn compact_top_settings_keeps_serious_mode_disclosure_semantically_reachable() {
    for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
        let service = VersionedConfigService::new("serious_mode = true\n".to_string()).unwrap();
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        **state = SettingsViewState::from_snapshot(&service.snapshot()).unwrap();
        let mut cx = view_cx_at(width, height);
        cx.motion.serious = true;
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        compiled.validate_parity().unwrap();
        let disclosure = compiled
            .semantic(&UiKey::new("settings/top/serious-mode"))
            .expect("compact Serious Mode disclosure");
        assert!(disclosure.label.contains("keeps every other effect off"));
        assert!(disclosure.rect.x >= -0.01 && disclosure.rect.y >= -0.01);
        assert!(disclosure.rect.right() <= width + 0.01);
        assert!(disclosure.rect.bottom() <= height + 0.01);
        assert!(
            compiled
                .paint
                .iter()
                .any(|node| node.key == UiKey::new("settings/top/serious-mode/visual")),
            "{width}×{height} keeps a bounded visual status"
        );
        assert!(
            compiled
                .semantic(&UiKey::new("settings/top/serious-mode/visual"))
                .is_none(),
            "{width}×{height} publishes only the complete status"
        );
        for hit in &compiled.hits {
            assert!(
                hit.rect.right() <= width + 0.01,
                "{width}×{height}: {hit:?}"
            );
            assert!(
                hit.rect.bottom() <= height + 0.01,
                "{width}×{height}: {hit:?}"
            );
        }
    }
}

#[test]
fn top_settings_paints_direct_labels_but_keeps_complete_label_semantics() {
    let (runtime, _instance, view) = setup();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    let field = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_THEME)
        .unwrap();
    let expected_visual = field.label.to_string();
    let row = top_setting_row(
        state,
        prefs::EDIT_THEME,
        None,
        SettingsWidth::Wide,
        LogicalRect::new(0.0, 0.0, 900.0, 80.0),
        true,
    )
    .unwrap();
    let compiled = UiTree::new(row)
        .compile(LogicalRect::new(0.0, 0.0, 900.0, 80.0))
        .unwrap();
    let wrapper_key = UiKey::new(format!("settings/label/{}", prefs::EDIT_THEME));
    let semantic = compiled.semantic(&wrapper_key).unwrap();
    assert!(
        semantic.label.starts_with(&expected_visual),
        "{}",
        semantic.label
    );
    let visual_key = UiKey::new(format!("settings/label/{}/visual", prefs::EDIT_THEME));
    let visual = compiled
        .paint
        .iter()
        .find_map(|node| {
            (node.key == visual_key)
                .then_some(&node.content)
                .and_then(|content| {
                    let UiContent::Text(spec) = content else {
                        return None;
                    };
                    Some(spec.text.as_str())
                })
        })
        .unwrap();
    assert_eq!(visual, expected_visual);
    assert!(!visual.contains("Default"));
    assert!(!visual.contains("Override"));
    assert!(compiled.semantic(&visual_key).is_none());
}

/// THE MUSIC EFFECTS STATUS SAYS WHAT REALLY SILENCES ITS VOICES, AND NOTHING
/// ELSE: no output, volume 0, a trail that draws nothing (the typing notes
/// alone) and a reduced motion policy (the bonk and the streak's note alone,
/// by the voice table). This window's focus is not a gate: the chime plays
/// from any window and each window plays its own keys.
#[test]
fn music_suppression_resolver_covers_every_reason_and_priority() {
    let motion = crate::native_app::ViewMotionCx::default();
    // The cursor effects switch's absent-key default is platform-split
    // (`app_config::DEFAULT_DECORATIVE_EFFECTS`), so an inherited default
    // would change which reason a case reaches. Each case therefore ASKS for
    // the switch unless it authors one itself; the typing-notes rung below
    // reaches its reason through `cursor_trail_style = "off"`.
    let state = |config: Config| {
        SettingsViewState::new(&Config {
            cursor_trail: config.cursor_trail.or(Some(true)),
            ..config
        })
    };
    let reduced = || Config {
        motion: Some("reduced".to_string()),
        ..Config::default()
    };

    assert_eq!(
        top_music_suppression_reason_for_output(&state(Config::default()), motion, false),
        Some(MusicStatus::NoOutput { saved_on: true })
    );
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config {
                trail_sounds: Some(false),
                ..Config::default()
            }),
            motion,
            false,
        ),
        Some(MusicStatus::NoOutput { saved_on: false })
    );
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config {
                trail_sounds: Some(false),
                ..Config::default()
            }),
            motion,
            true,
        ),
        None,
        "an authored Off switch is not described as suppressed"
    );
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config {
                serious_mode: Some(true),
                ..Config::default()
            }),
            motion,
            true,
        ),
        None,
        "Serious Mode projects the switch Off instead of claiming it is On"
    );

    let all_runtime_suppressions = crate::native_app::ViewMotionCx {
        focused: false,
        system_reduced: true,
        performance_reduced: true,
        ..motion
    };
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config {
                cursor_trail_style: Some("off".to_string()),
                trail_sound_volume: Some(0.0),
                ..reduced()
            }),
            all_runtime_suppressions,
            true,
        ),
        Some(MusicStatus::VolumeZero),
        "what silences every sound outranks what silences some"
    );
    // ONLY THE TYPING NOTES need a drawn trail: the chime, the bonk, the riff
    // and the output sounds play without one, so the status claims no silence.
    for style in ["off", "pack:", "pack:missing"] {
        let reason = top_music_suppression_reason_for_output(
            &state(Config {
                cursor_trail_style: Some(style.to_string()),
                ..reduced()
            }),
            motion,
            true,
        );
        assert_eq!(
            reason,
            Some(MusicStatus::TypingNotesOff),
            "{style:?} draws no trail, the larger silence beside Reduce motion's"
        );
        assert_eq!(reason.map(MusicStatus::visual), Some("Typing notes off"));
    }
    // A TYPO IS NOT A SILENCER. It resolves to the default style and the
    // trail renders, so the synth keeps its voice — only a resolution that
    // draws nothing takes it away.
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config {
                cursor_trail_style: Some("not-a-trail".to_string()),
                ..Config::default()
            }),
            motion,
            true,
        ),
        None,
        "an unknown style falls back to the default trail and still plays"
    );
    // A BACKGROUND WINDOW SILENCES NOTHING of a setting every window plays.
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config::default()),
            crate::native_app::ViewMotionCx {
                focused: false,
                ..motion
            },
            true,
        ),
        None,
        "this window's focus is not a gate of Music effects"
    );
    // REDUCE MOTION PAUSES ONLY THE VOICES WHOSE LIGHT IT STOPS, named in
    // the Motion picker's own words.
    let paused =
        top_music_suppression_reason_for_output(&state(reduced()), all_runtime_suppressions, true);
    assert_eq!(
        paused,
        Some(MusicStatus::MotionPaused(MotionReduction::Setting))
    );
    let full = paused.unwrap().full();
    assert!(
        full.starts_with("On. ")
            && full.contains(&reduce_motion_words())
            && full.contains("the bonk")
            && full.contains("the note when a program starts printing")
            && full.contains("other sounds still play")
            && !full.contains("silent"),
        "{full}"
    );
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config::default()),
            crate::native_app::ViewMotionCx {
                system_reduced: true,
                performance_reduced: true,
                ..motion
            },
            true,
        ),
        Some(MusicStatus::MotionPaused(MotionReduction::System)),
        "system policy has priority over the adaptive limiter"
    );
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config::default()),
            crate::native_app::ViewMotionCx {
                performance_reduced: true,
                ..motion
            },
            true,
        ),
        Some(MusicStatus::MotionPaused(MotionReduction::HeavyLoad))
    );
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config {
                load_adaptive_motion: Some(false),
                ..Config::default()
            }),
            crate::native_app::ViewMotionCx {
                performance_reduced: true,
                ..motion
            },
            true,
        ),
        None,
        "the authored adaptive-motion opt-out is respected"
    );
    assert_eq!(
        top_music_suppression_reason_for_output(
            &state(Config {
                motion: Some("full".to_string()),
                ..Config::default()
            }),
            crate::native_app::ViewMotionCx {
                system_reduced: true,
                performance_reduced: true,
                ..motion
            },
            true,
        ),
        None,
        "explicit Full overrides system and adaptive reduction"
    );
}

#[test]
fn music_effects_discloses_effective_motion_suppression_without_rewriting_toggle() {
    let auto = SettingsViewState::new(&Config::default());
    // Every resolver row (adaptive, Motion: Reduced, explicit Full, and the
    // no-output Saved On / Saved Off lines) is pinned host-independently by
    // `music_suppression_resolver_covers_every_reason_and_priority`; this test
    // is the render half, where system Reduce Motion reaches the compact page.
    assert!(
        top_projected_music_value(&auto),
        "authored switch remains On"
    );

    for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!()
            };
            state.page_reveal = Some(UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_TRAIL_SOUNDS
            )));
        }
        let mut cx = view_cx_at(width, height);
        cx.motion.system_reduced = true;
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let status = compiled
            .semantic(&UiKey::new("settings/top/music-effects/suppression"))
            .expect("the compact Music row carries its own suppression status");
        // Reduce Motion pauses some voices, never the switch: the status says
        // which, and that the rest play.
        assert!(
            status
                .label
                .contains(if crate::trail_audio::output_available() {
                    "System Reduce Motion pauses the bonk"
                } else {
                    "audio output is unavailable"
                }),
            "{}",
            status.label
        );
        let toggle = compiled
            .semantic(&UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_TRAIL_SOUNDS
            )))
            .unwrap();
        assert_eq!(toggle.value, SemanticValue::Bool(true));
    }
}

/// On a phone-sized page under Serious Mode, Cursor Styles keeps its
/// preview pinned and contained, says why the cursor has no trail, and every
/// style row scrolls whole into view.
#[test]
fn compact_serious_cursor_styles_keep_status_preview_and_every_style_reachable() {
    for (width, height) in [(320.0, 568.0), (568.0, 320.0)] {
        let (mut runtime, instance, view) = cursor_styles_runtime("serious_mode = true\n");
        let mut cx = view_cx_at(width, height);
        cx.motion.serious = true;
        let styles = {
            let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                unreachable!();
            };
            listed_cursor_styles(state)
        };
        let mut seen = BTreeSet::new();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            let context = format!("{width}×{height} screen {top}");
            compiled.validate_parity().unwrap();
            assert_zero_top_paint(compiled, &context);
            let preview = compiled
                .semantic(&UiKey::new("settings/preview/cursor-styles"))
                .unwrap_or_else(|| panic!("{context}: the preview stays pinned"));
            assert!(preview.rect.bottom() <= height + 0.01, "{context}");
            assert!(
                matches!(&preview.value, SemanticValue::Text(value) if value.contains("no trail")),
                "{context}: {:?}",
                preview.value
            );
            if let Some(status) = compiled.semantic(&UiKey::new("settings/cursor-styles/status")) {
                assert!(status.label.contains("Serious Mode"), "{context}");
                seen.insert("status".to_string());
            }
            for hit in &compiled.hits {
                assert!(hit.rect.right() <= width + 0.01, "{context}: {hit:?}");
                assert!(hit.rect.bottom() <= height + 0.01, "{context}: {hit:?}");
                if hit.key.as_str().starts_with("settings/cursor-style/") {
                    seen.insert(hit.key.as_str().to_string());
                }
            }
        });
        assert!(
            seen.contains("status"),
            "{width}×{height}: the Serious Mode note"
        );
        for style in &styles {
            assert!(
                seen.contains(&cursor_style_row_key(&style.value)),
                "{width}×{height}: {} unreachable",
                style.name
            );
        }
    }
}

#[test]
fn highlighted_motion_candidate_resolves_against_live_host_facts_before_commit() {
    let config: Config = aterm_toml::from_str("motion = \"reduced\"\n").unwrap();
    let mut state = SettingsViewState::new(&config);
    state.navigate(SettingsRoute::CursorMotion);
    let field = state
        .legacy
        .fields
        .iter()
        .find(|field| field.key == prefs::EDIT_MOTION)
        .expect("motion field");
    let picker = ChoicePicker::new(
        prefs::EDIT_MOTION,
        choices_for_field(field, &state.legacy.trail_pack_ids, &state.assets.themes)
            .expect("motion choices"),
        SettingsState::display_value(field),
        true,
        true,
        &effective_default_for_field(prefs::EDIT_MOTION),
    );
    state.choice_picker = Some(picker);
    let focus = |state: &mut SettingsViewState, value: &str| {
        let picker = state.choice_picker.as_ref().unwrap();
        // The default row (Automatic) writes nothing; it means `auto`.
        let index = picker
            .options
            .iter()
            .position(|option| option.value.as_deref().unwrap_or("auto") == value)
            .unwrap();
        state.common.last_focus = Some(UiKey::new(format!(
            "settings/choice/{}/{index}",
            prefs::EDIT_MOTION
        )));
    };

    // The SHIPPING Motion preview's verdict, not a test-side restatement of it.
    let preview_reduced_motion =
        |state: &SettingsViewState, motion: crate::native_app::ViewMotionCx| {
            renderer_preview_spec_for_key_with_font(
                state,
                prefs::EDIT_MOTION,
                100,
                motion,
                13.0,
                1.0,
                None,
            )
            .expect("the Motion row has a live preview")
            .reduced_motion
        };
    let constrained = crate::native_app::ViewMotionCx {
        system_reduced: true,
        performance_reduced: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    focus(&mut state, "full");
    assert!(
        !preview_reduced_motion(&state, constrained),
        "highlighted Full overrides OS and adaptive reduction"
    );
    focus(&mut state, "auto");
    assert!(preview_reduced_motion(&state, constrained));
    focus(&mut state, "reduced");
    assert!(preview_reduced_motion(
        &state,
        crate::native_app::ViewMotionCx::default()
    ));

    focus(&mut state, "auto");
    let load_only = crate::native_app::ViewMotionCx {
        system_reduced: false,
        performance_reduced: true,
        ..crate::native_app::ViewMotionCx::default()
    };
    assert!(preview_reduced_motion(&state, load_only));
    state
        .legacy
        .fields
        .iter_mut()
        .find(|field| field.key == prefs::EDIT_LOAD_ADAPTIVE_MOTION)
        .unwrap()
        .seed = Some("false".to_string());
    assert!(!preview_reduced_motion(&state, load_only));

    focus(&mut state, "full");
    assert!(preview_reduced_motion(
        &state,
        crate::native_app::ViewMotionCx {
            focused: false,
            ..crate::native_app::ViewMotionCx::default()
        }
    ));
    assert_eq!(
        state.raw_value(prefs::EDIT_MOTION).as_deref(),
        Some("reduced")
    );
}

fn setup() -> (
    NativeRuntime,
    crate::native_app::AppInstanceId,
    crate::native_app::ViewId,
) {
    setup_with_update(UpdateState::from_status(1, "0.1.0", None, false))
}

fn setup_with_update(
    update: UpdateState,
) -> (
    NativeRuntime,
    crate::native_app::AppInstanceId,
    crate::native_app::ViewId,
) {
    let app = SettingsApp::new(update);
    let mut runtime = NativeRuntime::new();
    let instance = runtime
        .insert_instance(NativeApp::Settings(Box::new(app)))
        .unwrap();
    let mut core_views = ViewStore::default();
    let view = core_views.insert_native(instance).unwrap();
    runtime
        .attach_view(
            view,
            instance,
            AppViewState::Settings(Box::new(SettingsViewState::new(&Config::default()))),
        )
        .unwrap();
    (runtime, instance, view)
}

fn replace_settings_source(
    runtime: &mut NativeRuntime,
    view: crate::native_app::ViewId,
    source: String,
) {
    let snapshot = VersionedConfigService::new(source)
        .expect("valid Settings fixture")
        .snapshot();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        panic!("Settings view");
    };
    **state = SettingsViewState::from_snapshot(&snapshot).expect("project Settings fixture");
}

/// EVERY RUNG OF THE SOFTWARE UPDATE PAGE ADMITS THE FAILED APPLIES.
///
/// The page collapses as the host narrows — hero label, headline, detail,
/// minimum-detail — and each rung is authored separately, which is how the
/// `installable` work once fixed a headline and left the card underneath
/// contradicting it. So the assertion runs the whole ladder: on the owner's
/// 2026-08-21 state (staged 0.56.0, two dead applies, `ChildDied`) none of them
/// may read as "Ready", and the widest rungs must name the count AND the cause.
#[test]
fn every_rung_of_the_update_page_admits_a_stage_that_failed_to_apply() {
    use crate::update_apply_trouble::ApplyRetry;

    let mut status = update_status(true);
    status.failing_applies = 2;
    status.outcome = "staged 0.2.0 (build 2) \u{2014} verified and ready to apply".to_string();
    let troubled = UpdateState::from_status(1, "0.1.0", Some(&status), false)
        .with_apply_lane(
            "overlap handoff failed safely: handoff proof ended ChildDied",
            ApplyRetry::Scheduled,
        )
        .projection();

    assert!(
        !troubled.apply_is_failing,
        "two is below the escalation threshold — the window the page used to \
         spend saying \"Ready\""
    );
    assert_eq!(compact_update_headline(&troubled), "Not installing");
    assert_eq!(compact_update_summary_detail(&troubled), "Not installing");
    let detail = compact_update_detail(&troubled);
    assert!(
        detail.contains("Tried twice") && detail.contains("didn\u{2019}t start"),
        "the compact detail names the count and the cause: {detail}"
    );
    assert!(
        !detail.contains("ChildDied"),
        "never the proof-outcome enum name: {detail}"
    );
    let minimum = compact_update_detail_minimum(&troubled);
    assert!(
        minimum.contains('2'),
        "the count survives to the tersest rung: {minimum}"
    );

    // A CLEAN STAGE IS UNCHANGED. Waiting for a quiet window records refusals,
    // never failures, so every rung must still read as plain readiness.
    let clean = UpdateState::from_status(1, "0.1.0", Some(&update_status(true)), false)
        .with_apply_lane(
            "overlap handoff failed safely: handoff proof ended ChildDied",
            ApplyRetry::Scheduled,
        )
        .projection();
    assert!(clean.apply_trouble.is_none());
    assert_eq!(compact_update_headline(&clean), "Ready");
    assert_eq!(compact_update_summary_detail(&clean), "Ready");
    assert_eq!(compact_update_detail(&clean), "Ready to install.");
    assert_eq!(compact_update_detail_minimum(&clean), "Ready.");
}

/// A BUILD ON HOLD IS NEVER STARTED FROM THE PAGE (the audit of
/// 2026-09-30): its sentence says starting it would roll it back, and the
/// page's one button still installed it. Nor does the button send a
/// check, which the updater refuses while a build is staged ("A verified
/// update is already ready to install"): it sends nothing and says the
/// build is on hold — also when the ledger no longer names the failures,
/// where the page says "on hold" at every width, never "ready".
/// NEGATIVE CONTROL: a build the person is asked to retry (`ManualOnly`)
/// installs, as before.
#[test]
fn the_update_button_never_starts_a_build_on_hold() {
    use crate::update_apply_trouble::ApplyRetry;
    let press = |failed: u32, retry: ApplyRetry, id: &str| {
        let on_hold = retry == ApplyRetry::NewerRelease;
        let mut status = update_status(true);
        status.failing_applies = failed;
        let update = UpdateState::from_status(1, "0.1.0", Some(&status), false)
            .with_apply_lane("handoff proof ended ChildDied", retry)
            .with_staged_on_hold(on_hold);
        let projection = update.projection();
        assert_eq!(projection.staged_on_hold, on_hold);
        if on_hold {
            let said = [
                projection.headline.clone(),
                projection.detail.clone().expect("detail"),
                compact_update_headline(&projection),
                compact_update_summary_detail(&projection).to_string(),
                compact_update_detail(&projection),
                compact_update_detail_minimum(&projection),
            ];
            assert!(
                said.iter().all(|line| !line.contains("ready")
                    && !line.contains("Ready")
                    && !line.contains("Install")),
                "{said:?}"
            );
            if failed == 0 {
                assert_eq!(projection.headline, "Update on hold");
                assert!(
                    said[1].contains("is on hold")
                        && said[1].contains(crate::update_words::NEWER_RELEASE_REPLACES),
                    "{said:?}"
                );
            }
        }
        let (mut runtime, instance, view) = setup_with_update(update);
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        let pressed = runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new(id),
                    value: None,
                }),
            )
            .unwrap();
        let request = pressed.effects.iter().find_map(|effect| match effect {
            AppEffect::Update { request, .. } => Some(*request),
            _ => None,
        });
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        (request, state.feedback.clone())
    };
    let held = Some(
        "aterm v0.2.0 is on hold: starting it would roll it back \u{2014} a newer release \
         replaces it by itself"
            .to_string(),
    );
    for id in ["updates/install-now", "updates/check"] {
        assert_eq!(press(2, ApplyRetry::NewerRelease, id), (None, held.clone()));
        assert_eq!(press(0, ApplyRetry::NewerRelease, id), (None, held.clone()));
    }
    assert_eq!(
        press(2, ApplyRetry::ManualOnly, "updates/install-now").0,
        Some(UpdateRequest::InstallAndRelaunch)
    );
}

fn update_status(staged: bool) -> aterm_update::UpdateStatus {
    aterm_update::UpdateStatus {
        linux: None,
        enabled: true,
        current_build: 1,
        staged_build: staged.then_some(2),
        staged_version: staged.then(|| "0.2.0".to_string()),
        staged_commit: staged.then(|| "deadbeef".to_string()),
        staged_dmg_sha256: staged.then(|| "0".repeat(64)),
        changelog: staged
            .then(|| "### Better\n- compact Settings\n- semantic previews".to_string()),
        outcome: "Update service healthy".to_string(),
        updated_at: String::new(),
        failing_checks: 0,
        failing_kind: String::new(),
        failing_applies: 0,
        installable: true,
        failing_since: String::new(),
        failing_persistent: false,
        failing_checks_kind: String::new(),
        channel_unreadable: false,
    }
}

