#[test]
fn focusing_search_closes_invisible_picker_and_confirmation_before_one_escape() {
    let (mut runtime, instance, view) = setup();
    let _ = compile_settings_view(&runtime, instance, view, &view_cx());
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_THEME)),
                value: None,
            }),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        unreachable!()
    };
    assert!(state.choice_picker.is_some());
    state.reset_all_confirmation = true;
    state.feedback = Some("Reset all settings?".to_string());

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new("settings/search"))),
        )
        .unwrap();
    runtime
        .dispatch(instance, view, AppEvent::InsertText("font".to_string()))
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    assert!(state.choice_picker.is_none());
    assert!(!state.reset_all_confirmation);
    assert_eq!(state.search, "font");

    runtime
        .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Cancel))
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!()
    };
    assert!(state.search.is_empty(), "one Escape clears Search");
    assert!(state.search_input.value().is_empty());
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some("settings/nav/home")
    );
}

#[test]
fn singleton_controller_supports_distinct_window_local_views() {
    let (mut runtime, instance, first) = setup();
    let mut core_views = ViewStore::default();
    // Burn the first core id to mirror the id already held by `first`; stable
    // view ids are globally allocated by App in production.
    let _ = core_views.insert_native(instance).unwrap();
    let second = core_views.insert_native(instance).unwrap();
    assert_ne!(first, second);
    runtime
        .attach_view(
            second,
            instance,
            AppViewState::Settings(Box::new(SettingsViewState::new(&Config::default()))),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            first,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    let Some(AppViewState::Settings(first_state)) = runtime.view_state(first) else {
        panic!("first Settings view");
    };
    let Some(AppViewState::Settings(second_state)) = runtime.view_state(second) else {
        panic!("second Settings view");
    };
    assert_eq!(first_state.route, SettingsRoute::About);
    assert_eq!(second_state.route, SettingsRoute::Home);
    assert_eq!(
        runtime.instance_by_kind(crate::native_app::AppKind::Settings),
        Some(instance)
    );
}

#[test]
fn pointer_activation_opens_choice_surface_then_selection_patches() {
    let (mut runtime, instance, view) = setup();
    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_MOTION)),
                value: None,
            }),
        )
        .unwrap();
    assert!(
        !outcome
            .effects
            .iter()
            .any(|effect| matches!(effect, AppEffect::ConfigPatch { .. })),
        "opening choices must not silently change configuration"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view");
    };
    let picker = state
        .choice_picker
        .as_ref()
        .expect("a choice too wide for segments opens the picker");
    assert_eq!(picker.key, prefs::EDIT_MOTION);
    let index = picker
        .options
        .iter()
        .position(|option| option.value.is_some())
        .expect("an option other than the default");
    let outcome = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/choice/{}/{index}", prefs::EDIT_MOTION)),
                value: None,
            }),
        )
        .unwrap();
    let edit = outcome.effects.iter().find_map(|effect| match effect {
        AppEffect::ConfigPatch { patch, .. } => patch.edits.first(),
        _ => None,
    });
    let edit = edit.expect("choice activation emits a durable patch");
    assert_eq!(edit.key, prefs::EDIT_MOTION);
    assert!(
        edit.value
            .as_deref()
            .is_some_and(|value| prefs::MOTION_MODES.contains(&value))
    );
    // The choice edit carries the UI-observed value.
    let ExpectedConfigValue::Exact(expected) = &edit.expected;
    assert_ne!(&edit.value, expected);
}

