#[test]
fn exact_phone_special_routes_have_zero_renderer_text_overflow() {
    at_each_text_scale(
        &[1.0, 2.0],
        "exact-phone overflow audit",
        exact_phone_special_routes_have_zero_renderer_text_overflow_at_scale,
    );
}

/// One rung of [`exact_phone_special_routes_have_zero_renderer_text_overflow`] ([`at_each_text_scale`]).
fn exact_phone_special_routes_have_zero_renderer_text_overflow_at_scale(scale: f32) {
    let cx = view_cx_at(286.5, 558.0);
    let assert_fits = |compiled: &crate::native_ui::CompiledUi, context: &str| {
        let audit = compiled.paint_audit_lines();
        let overflow = audit
            .iter()
            .filter(|line| line.contains("overflow=true"))
            .cloned()
            .collect::<Vec<_>>();
        assert!(
            overflow.is_empty(),
            "{context} has renderer text overflow:\n{}",
            overflow.join("\n")
        );
        assert!(
            audit
                .first()
                .is_some_and(|line| line.contains("overflow=0")),
            "{context} publishes a zero-overflow summary"
        );
    };

    // Settings ▸ Messages, its longest entry expanded (the crash record's
    // absolute path and its second line), through every view the list
    // scrolls through (ruling 264): every chip, row, meta and detail line
    // fits its box — no renderer text overflow, no semantic node clipped
    // below the viewport, paint and semantics in parity — and the expanded
    // entry's detail, action and Copy, and the next entry, are all reached.
    // The log of one day, and the same log spread over five days, so its
    // day headers (ruling 273) ride every view too.
    for (log, fixture) in [
        (sample_messages(), "one day"),
        (multi_day_messages(), "days"),
    ] {
        let (mut runtime, instance, view) = setup_with_messages();
        assert!(runtime.replace_settings_messages(log, 8));
        select_message(&mut runtime, instance, view, 40);
        let mut seen = BTreeSet::new();
        scroll_messages_through(&mut runtime, instance, view, &cx, 1, |compiled, k| {
            compiled.validate_parity().unwrap();
            assert_fits(compiled, &format!("Messages ({fixture}) view {k}"));
            for node in &compiled.semantics {
                if node.key.as_str().starts_with("settings/messages/") {
                    assert!(
                        node.rect.bottom() <= cx.viewport.bottom() + 0.01,
                        "{} is clipped in view {k} at {scale}\u{00d7}: {:?}",
                        node.key.as_str(),
                        node.rect
                    );
                    seen.insert(node.key.as_str().to_string());
                }
            }
        });
        for key in [
            "settings/messages/row/40/detail/0",
            "settings/messages/row/40/action/0",
            "settings/messages/row/40/copy",
            "settings/messages/row/1/title",
        ] {
            assert!(
                seen.contains(key),
                "missing {key} ({fixture}) at {scale}\u{00d7}"
            );
        }
        assert_eq!(
            seen.iter()
                .any(|key| key.starts_with("settings/messages/day/")),
            fixture == "days",
            "day headers only on the log of days ({scale}\u{00d7})"
        );
    }

    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
        assert_fits(compiled, &format!("About screen {top}"));
    });

    for staged in [false, true] {
        let update = update_status(staged);
        let (mut runtime, instance, view) =
            setup_with_update(UpdateState::from_status(1, "0.1.0", Some(&update), false));
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::SoftwareUpdate),
                    value: None,
                }),
            )
            .unwrap();
        each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
            assert_fits(
                compiled,
                &format!("Software Update staged={staged} screen {top}"),
            );
        });
    }
}

#[test]
fn text_edit_ownership_follows_exact_focus_click_and_navigation() {
    let (mut runtime, instance, view) = setup();
    let text_key = prefs::EDIT_FONT_FAMILY;
    let text_focus = UiKey::new(format!("settings/control/{text_key}"));

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(text_focus.clone())),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Commit("Mono ".to_string())),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view");
    };
    assert_eq!(state.editing_field.as_deref(), Some(text_key));
    assert_eq!(state.field_inputs[text_key].value(), "Mono ");

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_CURSOR_BLINK
            )))),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Commit("invisible".to_string())),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.editing_field.is_none());
    assert_eq!(state.field_inputs[text_key].value(), "Mono ");
    assert!(state.search_input.value().is_empty());

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(text_focus.clone())),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/page-scroll"),
                value: Some(SemanticInput::Number(0.0)),
            }),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(
        state.editing_field.is_none(),
        "another control's action blurs the field"
    );

    runtime
        .dispatch(instance, view, AppEvent::FocusChanged(Some(text_focus)))
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::About),
                value: None,
            }),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.editing_field.is_none());
    assert_eq!(state.route, SettingsRoute::About);
}

#[test]
fn escape_discards_field_draft_while_ordinary_blur_preserves_it() {
    let (mut runtime, instance, view) = setup();
    let text_key = prefs::EDIT_FONT_FAMILY;
    let text_focus = UiKey::new(format!("settings/control/{text_key}"));
    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
        panic!("Settings view");
    };
    state
        .legacy
        .fields
        .iter_mut()
        .find(|field| field.key == text_key)
        .unwrap()
        .seed = Some("Committed Mono".to_string());

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(text_focus.clone())),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::SelectAll),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Commit("Retained Draft".to_string())),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new(format!(
                "settings/control/{}",
                prefs::EDIT_CURSOR_BLINK
            )))),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(text_focus.clone())),
        )
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.field_inputs[text_key].value(), "Retained Draft");

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::SelectAll),
        )
        .unwrap();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::TextInput(TextInputEvent::Commit("Cancelled Draft".to_string())),
        )
        .unwrap();
    runtime
        .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Cancel))
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert!(state.editing_field.is_none());
    assert!(!state.field_inputs.contains_key(text_key));

    runtime
        .dispatch(instance, view, AppEvent::FocusChanged(Some(text_focus)))
        .unwrap();
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(
        state.field_inputs[text_key].value(),
        "Committed Mono",
        "Escape reopens from committed reducer state, never the cancelled draft"
    );
}

#[test]
fn inline_preview_viewports_publish_exact_non_phantom_scroll_bounds() {
    for cx in [view_cx_at(600.0, 589.0), view_cx_at(1_200.0, 820.0)] {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: route_action(SettingsRoute::Appearance),
                    value: None,
                }),
            )
            .unwrap();
        let first = compile_settings_view(&runtime, instance, view, &cx);
        assert!(
            first
                .semantic(&UiKey::new("settings/preview/appearance"))
                .is_some(),
            "the renderer preview is pinned at {}x{}",
            cx.viewport.width,
            cx.viewport.height
        );
        // The bound is the least first stop whose screen reaches the last
        // stop: that screen is full, and one stop earlier would not reach.
        let (plan, limit) = {
            let state = messages_view_state(&runtime, view);
            let plan = state.scroll_plan().expect("a measured list");
            (plan.clone(), state.result_page_limit.get())
        };
        assert_eq!(limit, Some(plan.limit()));
        let limit = plan.limit();
        assert_eq!(plan.view(limit).end, plan.len());
        if limit > 0 {
            assert!(plan.view(limit - 1).end < plan.len());
        }

        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/page-scroll"),
                    value: Some(SemanticInput::Number(f64::MAX)),
                }),
            )
            .unwrap();
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        for event in [AppEvent::ScrollLines(1), AppEvent::ScrollPage(1)] {
            runtime.dispatch(instance, view, event).unwrap();
            let _ = compile_settings_view(&runtime, instance, view, &cx);
            assert_eq!(
                messages_view_state(&runtime, view).page_scroll,
                limit,
                "the list scrolled past its last screen at {}x{}",
                cx.viewport.width,
                cx.viewport.height
            );
        }
    }
}

#[test]
fn tall_special_pages_publish_zero_bound_and_never_scroll() {
    let cx = view_cx_at(1_200.0, 1_400.0);
    for route in [
        SettingsRoute::Home,
        SettingsRoute::Manual,
        SettingsRoute::SoftwareUpdate,
        SettingsRoute::Packages,
        SettingsRoute::About,
    ] {
        let (mut runtime, instance, view) = setup();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(route);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            unreachable!();
        };
        assert_eq!(
            state.result_page_limit.get(),
            Some(0),
            "{} renders its complete tall dashboard",
            route.label()
        );
        assert!(
            compiled
                .paint
                .iter()
                .all(|node| !node.key.as_str().ends_with("/thumb")),
            "{} shows its whole list at once",
            route.label()
        );

        for event in [
            AppEvent::ScrollLines(1),
            AppEvent::ScrollPage(1),
            AppEvent::Action(ActionInvocation {
                id: ActionId::new("settings/page-scroll"),
                value: Some(SemanticInput::Number(f64::MAX)),
            }),
        ] {
            runtime.dispatch(instance, view, event).unwrap();
            let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
                unreachable!();
            };
            assert_eq!(
                state.page_scroll,
                0,
                "{} admitted a phantom special-page state",
                route.label()
            );
        }
    }
}

#[test]
fn pending_config_key_is_busy_and_rejects_a_second_mutation() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::CursorMotion),
                value: None,
            }),
        )
        .unwrap();
    let action = ActionId::new(format!("settings/set/{}", prefs::EDIT_CURSOR_BLINK));
    let first = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: action.clone(),
                value: Some(SemanticInput::Bool(false)),
            }),
        )
        .unwrap();
    assert_eq!(
        first
            .effects
            .iter()
            .filter(|effect| matches!(effect, AppEffect::ConfigPatch { .. }))
            .count(),
        1
    );

    let second = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: action,
                value: Some(SemanticInput::Bool(true)),
            }),
        )
        .unwrap();
    assert!(
        second
            .effects
            .iter()
            .all(|effect| !matches!(effect, AppEffect::ConfigPatch { .. })),
        "one key cannot enqueue a second write before its first completion"
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        unreachable!();
    };
    assert_eq!(state.pending.len(), 1);

    let cx = view_cx();
    let compiled = runtime
        .render(instance, view, &cx)
        .unwrap()
        .compile(cx.viewport)
        .unwrap();
    let control = compiled
        .semantic(&UiKey::new(format!(
            "settings/control/{}",
            prefs::EDIT_CURSOR_BLINK
        )))
        .unwrap();
    let state = control.state.unwrap();
    assert!(!state.enabled);
    assert!(state.busy);
}

#[test]
fn scrolling_windows_rows_without_changing_stable_keys() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(SettingsRoute::Appearance),
                value: None,
            }),
        )
        .unwrap();
    let cx = view_cx();
    let visible = |runtime: &NativeRuntime| {
        runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap()
            .semantics
            .into_iter()
            .filter(|node| setting_control_key(node.key.as_str()))
            .map(|node| node.key)
            .collect::<Vec<_>>()
    };
    // Lay the list out, then scroll past the page's pointer to Top Settings
    // to its rows.
    let _ = visible(&runtime);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    let before = visible(&runtime);
    assert!(before.len() > 2, "test requires a window, got {before:?}");
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    let after = visible(&runtime);
    assert_eq!(before[1], after[0], "one-row scroll preserves row identity");
    assert_ne!(before[0], after[0]);
}

#[test]
fn clear_search_is_visible_touchable_and_resets_the_complete_query_state() {
    for (width, height) in [(390.0, 568.0), (1_200.0, 820.0)] {
        let (mut runtime, instance, view) = setup();
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/search"),
                    value: Some(SemanticInput::Text("font".to_string())),
                }),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            panic!("Settings view")
        };
        state.search_input.select_all();
        state.page_scroll = 4;

        let cx = view_cx_at(width, height);
        let compiled = runtime
            .render(instance, view, &cx)
            .unwrap()
            .compile(cx.viewport)
            .unwrap();
        let clear = compiled
            .semantic(&UiKey::new("settings/search-clear"))
            .expect("nonempty search exports visible Clear");
        assert!(clear.rect.width >= 44.0 && clear.rect.height >= 32.0);
        // 2026-08 settings audit: the fixed 52pt box painted "Cl…" — the
        // authored width must fit the whole word in the UI face.
        let clear_paint = compiled
            .paint_audit_lines()
            .into_iter()
            .find(|line| {
                line.starts_with("paint-text") && line.contains("\"settings/search-clear\"")
            })
            .expect("Clear button paints text");
        assert!(
            clear_paint.contains("overflow=false") && clear_paint.contains("painted=\"Clear\""),
            "the visual Clear must fit its authored box: {clear_paint}"
        );
        assert!(
            compiled
                .hits
                .iter()
                .any(|hit| hit.key.as_str() == "settings/search-clear")
        );

        runtime
            .dispatch(
                instance,
                view,
                AppEvent::Action(ActionInvocation {
                    id: ActionId::new("settings/search-clear"),
                    value: None,
                }),
            )
            .unwrap();
        let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
            panic!("Settings view")
        };
        assert!(state.search.is_empty());
        assert!(state.search_input.value().is_empty());
        assert_eq!(state.search_input.selection().range(), 0..0);
        assert_eq!(state.page_scroll, 0);
        assert_eq!(
            state.common.last_focus.as_ref().map(UiKey::as_str),
            Some("settings/search")
        );
    }
}

