/// A LOG AS A WORKING MAC KEEPS IT (round 14 capture): about forty
/// records from every family, each built by its real reporter (or, for a
/// script, parsed by the wire's own `notice` grammar) and posted into a
/// headless App's center at its own minute over the last few hours; the
/// page's state is then the host's own projection (`App::messages_state`).
/// Two facts a headless App cannot have are set on the projection as the
/// host publishes them on a Mac that wrote its logs: the log folder, and
/// a crash log that is still on disk (so `Open log` can be pressed).
fn realistic_messages() -> MessagesState {
    use crate::message_reporters::{self as rep, ConfigFamily, ConfigWarnings, PackagesVerb};
    use crate::{toolchain_words, update_words};
    use aterm_messages::{Hold, Message, Meter, PIECE_SEP, STRAIN_KEY, Severity, WallStamp, tags};
    let mut app = crate::App::headless_for_test();
    app.clear_messages_for_test();
    let now = crate::messages_host::wall_stamp_now().unix_ms;
    let stamp = |minutes_ago: u64| WallStamp {
        unix_ms: now - minutes_ago * 60_000,
    };
    let strain_record = |severity: Severity, title: &str, lines: &[String]| {
        Message::new(tags::SYSTEM, severity, title)
            .key(STRAIN_KEY)
            .hold(Hold::LogOnly)
            .lines(lines.iter().cloned())
    };
    let sep = PIECE_SEP;
    let mut config = ConfigWarnings::default();
    config.push(
        ConfigFamily::Keybindings,
        "config keybindings: skipping \"ctrl+x\": unknown action \"foo\"".into(),
    );
    config.push(
        ConfigFamily::IgnoredKeys,
        "config line 3: windw_padding \u{2014} did you mean \"window_padding\"? \
         (no effect in this build)"
            .into(),
    );
    config.push(
        ConfigFamily::UnacceptedValues,
        "config cursor_style: \"blob\" is not one of block, bar, underline; ignored".into(),
    );
    for key in ["trail_length", "trail_fade"] {
        config.push(
            ConfigFamily::CursorTrail,
            format!("config {key}: out of range; the default is used"),
        );
    }
    config.push(
        ConfigFamily::Restart,
        "gpu applies on next launch (the renderer backend is chosen at startup)".into(),
    );
    // Oldest first: (minutes ago, message).
    let mut posts: Vec<(u64, Message)> = vec![
        (
            412,
            rep::crash_message(&crate::logging::CrashEvidence {
                path: std::path::PathBuf::from(
                    "/Users//ana/Library/Logs/aterm/crash-signal-11-1758461234.log.seen",
                ),
                head: vec![
                    "fatal signal 11 (SIGSEGV) in thread 'render'".into(),
                    "at aterm_render::glyph_cache::GlyphCache::insert+0x1f4".into(),
                ],
            }),
        ),
        (
            410,
            update_words::landed("0.91.0", 1233, 3, Some(std::time::Duration::from_secs(42))),
        ),
        (
            405,
            toolchain_words::managed_current(
                "claude 2.1.280 (Anthropic latest); codex 0.156.0 (OpenAI latest)",
                0,
                true,
                toolchain_words::HookDialect::Zsh,
            )
            .expect("a managed-current record"),
        ),
        (
            398,
            rep::session_connection_created(
                "\u{21c6} Connected to m3.local \u{2014} 2 sessions shared",
            ),
        ),
        (
            390,
            rep::file_access_question(&crate::consent_card::NeedWords::sample()),
        ),
        (388, rep::file_access_granted()),
        (
            372,
            // The plain sentence first — the cause and the next step — the
            // raw error and its stderr last (ruling 262).
            toolchain_words::failed(
                "Disk full. Free about 3 GB, then retry from Packages. Build 5519 \
                 still works.\n\
                 ay stage failed: could not extract trust-5520.tar.zst into \
                 ~/.atpkg/store/trust/5520: No space left on device (os error 28)\n\
                 stderr: tar: trust-5520/lib/rustlib/aarch64-apple-darwin/lib/\
                 librustc_driver.dylib: Cannot write: No space left on device",
            ),
        ),
        (
            366,
            toolchain_words::first_run_short(
                toolchain_words::FirstRunShort::Failed,
                "could not reach the index: dns error: failed to lookup address \
                 information: nodename nor servname provided, or not known",
            ),
        ),
        (360, rep::packages_verb_row(PackagesVerb::Check)),
        (
            344,
            strain_record(
                Severity::Info,
                "Typing slowed by 'yes' in tab 2 for 2m 10s",
                &[
                    format!("top: 'yes' in tab 2 7.9 cores{sep}'cargo' 1.2{sep}aterm 0.3"),
                    format!("typing: 14 of 40 keys over 60 ms{sep}worst 620 ms"),
                    format!("memory: pressure normal{sep}17.8 GB in use"),
                    format!("heat: fair{sep}Low Power Mode off"),
                    "shown for 2m 0s".into(),
                ],
            ),
        ),
        (
            331,
            rep::new_tab_failed("fork: Resource temporarily unavailable (os error 35)"),
        ),
        (
            330,
            rep::split_refused(
                "Split refused: this pane is 20x5 cells; a vertical split needs at least 20x7",
            ),
        ),
        (
            322,
            rep::presence_not_saved(
                "window-state.json",
                "window positions",
                "Permission denied (os error 13)",
                false,
            ),
        ),
        (315, rep::gpu_lost()),
        (
            314,
            rep::backdrop_declined(
                "Backdrop image not shown",
                "~/Pictures/dunes.heic is 9600x6400; the limit is 8192 px a side",
            ),
        ),
        (
            300,
            rep::a11y_publisher_dead("the accessibility bridge thread exited", true),
        ),
        (
            288,
            rep::fabric_failure(
                "post",
                "Couldn't deliver a message",
                &[
                    "peer @m3 did not answer in 10 s",
                    "queued; it retries on reconnect",
                ],
            ),
        ),
        (
            286,
            rep::fabric_status("hold", "Session held", "the fleet holds it", true),
        ),
        (
            285,
            rep::hold_refused(false, "only the session's owner can lift a hold"),
        ),
        (
            270,
            rep::harness_note("claude: reviewing diff in tab 3 (12 files)"),
        ),
        (
            262,
            rep::shell_lost_in_update("the pty handed over was closed (os error 9)"),
        ),
        (
            261,
            rep::restored_tab_failed("fork: Resource temporarily unavailable (os error 35)"),
        ),
        (255, rep::keystrokes_dropped(3)),
        (
            240,
            strain_record(
                Severity::Warn,
                "Typing slowed by low memory for 45 s",
                &[
                    format!("top: 'Google Chrome' 6.0 GB{sep}'Docker' 4.1 GB{sep}aterm 1.2 GB"),
                    format!("typing: 9 of 22 keys over 60 ms{sep}worst 1400 ms"),
                    format!("memory: pressure critical{sep}23.6 GB in use{sep}swap 38 MB/s"),
                    "shown for 41 s".into(),
                ],
            ),
        ),
        (
            226,
            update_words::health_warning(
                update_words::HealthKind::Download,
                aterm_update::health_failing_title("pipeline"),
                "20 failed checks in a row since 2026-08-27T22:04:36Z: release manifests \
                 exist but cannot be downloaded.",
            ),
        ),
        (
            214,
            update_words::download_failed(
                "0.92.0",
                "the download stopped at 46 MB of 74 MB: connection reset by peer",
            ),
        ),
        (
            190,
            toolchain_words::appnotice(
                tags::TOOLCHAIN,
                "aterm pkg install claude: claude 2.1.281 installed",
            ),
        ),
        (
            150,
            strain_record(
                Severity::Info,
                "Typing slowed by Spotlight indexing for 1m 5s",
                &[
                    "top: Spotlight indexing 3.4 cores".into(),
                    "disk: I/O stall 38%".into(),
                    "not shown: no typing".into(),
                ],
            ),
        ),
        (
            96,
            update_words::needs_install_because(
                "Couldn't install aterm v0.92.0",
                update_words::short_cause("rename: No space left on device (os error 28)"),
                update_words::INSTALL_FROM_MENU,
                Severity::Warn,
                1234,
            ),
        ),
        (
            40,
            update_words::staged(
                "0.92.0",
                1234,
                Some(update_words::ApplyPosture::ManualByConfig),
            ),
        ),
        (
            12,
            Message::new(tags::SYSTEM, Severity::Info, "Typing slowed by 'yes'")
                .key(STRAIN_KEY)
                .hold(Hold::Live {
                    stale_after: aterm_messages::STALE_STRAIN,
                })
                .meter(Meter::level(740, "6 of 8 cores"))
                .no_excerpt()
                .line(format!("top: 'yes' in tab 2 5.9 cores{sep}aterm 0.4")),
        ),
    ];
    for (k, msg) in config.into_messages().into_iter().enumerate() {
        posts.push((420 - k as u64, msg));
    }
    posts.push((
        380,
        rep::font_family_rejected(
            "config font_family_bold: \"Nope\" is not an admissible font (not found); ignored",
        ),
    ));
    for (k, msg) in toolchain_words::machine_settings("universal-control disabled")
        .into_iter()
        .enumerate()
    {
        posts.push((404 - k as u64, msg));
    }
    posts.sort_by_key(|(minutes, _)| std::cmp::Reverse(*minutes));
    // Scripts, through the wire's own grammar (`aterm ctl notice …`),
    // interleaved with the reporters' posts in time order.
    let scripts: [(u64, &str); 3] = [
        (
            180,
            "post deploy sev=warn Deploy to staging failed -- exit status 2\\nsee deploy.log",
        ),
        (
            120,
            "post backup Nightly backup finished -- 4.2 GB in 3m 12s\\nto /Volumes/Archive",
        ),
        (60, "progress index pct=40 Indexing the photo library"),
    ];
    let mut scripts = scripts.into_iter().peekable();
    let wire = |app: &mut crate::App, minutes: u64, line: &str| {
        let req = aterm_messages::wire::NoticeRequest::parse(line).expect("a notice line");
        let applied = aterm_messages::wire::apply(
            &mut app.messages,
            &mut app.wire_gate,
            req,
            stamp(minutes),
            std::time::Instant::now(),
        );
        assert!(applied.reply.starts_with("OK"), "{line}: {}", applied.reply);
    };
    for (minutes, msg) in posts {
        while let Some((at, line)) = scripts.next_if(|(at, _)| *at > minutes) {
            wire(&mut app, at, line);
        }
        app.post_message_at(msg, stamp(minutes));
    }
    for (at, line) in scripts {
        wire(&mut app, at, line);
    }
    let mut state = app.messages_state();
    state.log_folder = Some("/Users//ana/Library/Logs/aterm".to_string());
    state.saved = true;
    for entry in &mut state.entries {
        if entry.tag == "crash" {
            for action in &mut entry.actions {
                action.still_actionable = true;
            }
        }
    }
    state
}

/// A Settings controller holding `messages`, its view on Messages.
fn setup_with_these_messages(
    messages: MessagesState,
) -> (
    NativeRuntime,
    crate::native_app::AppInstanceId,
    crate::native_app::ViewId,
) {
    let (mut runtime, instance, view) = setup();
    let revision = messages.revision.max(1);
    assert!(runtime.replace_settings_messages(messages, revision));
    go_to_route(&mut runtime, instance, view, SettingsRoute::Messages);
    (runtime, instance, view)
}

/// Navigate the view to `route` by its own action, as the rail does.
fn go_to_route(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    route: SettingsRoute,
) {
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: route_action(route),
                value: None,
            }),
        )
        .unwrap();
}

/// Rasterize the view as it compiles now at `width`×`height` in `theme`
/// and write it to `path` (2× pixels).
fn shoot_settings(
    runtime: &NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    (width, height): (f32, f32),
    theme: aterm_render::Theme,
    path: &std::path::Path,
) -> crate::native_ui::CompiledUi {
    let surface = crate::settings::Roles::from_theme(theme).surface;
    let compiled = compile_settings_view(runtime, instance, view, &view_cx_at(width, height));
    let (rgba, pw, ph) = crate::tray_raster::rasterize_tray(
        &compiled.tray(theme, 13.0).prims,
        width as u32,
        height as u32,
        2.0,
        [surface[0], surface[1], surface[2], 255],
    );
    let mut out = Vec::new();
    {
        let mut enc = aterm_png::Encoder::new(&mut out, pw, ph);
        enc.set_color(aterm_png::ColorType::Rgba);
        enc.set_depth(aterm_png::BitDepth::Eight);
        enc.write_header()
            .expect("png header")
            .write_image_data(&rgba)
            .expect("png data");
    }
    std::fs::write(path, &out).expect("write png");
    crate::logging::stderr_line!("wrote {} ({pw}x{ph})", path.display());
    compiled
}

/// VISUAL CAPTURE of the log's DAY HEADERS (design ruling 273): the
/// realistic log ([`realistic_messages`]) spread over five local days, at
/// the Settings pages a 100- and a 60-column window open (774 and 470 pt
/// wide, 612 tall), dark and GitHub Light — the list's top, one scrolled
/// to the middle of a day, the end, the Problems filter, an entry opened
/// under a past day, and High Contrast. Not part of a test run: `#[ignore]`d.
///
/// ```sh
/// SETTINGS_MESSAGES_PNG_DIR=<dir> targo --unverified test -p aterm-gui --lib \
///     settings_messages_day_headers_capture -- --ignored --nocapture
/// ```
#[test]
#[ignore = "visual capture: needs a system UI face; run with --ignored"]
fn settings_messages_day_headers_capture() {
    const DAY: u64 = 86_400_000;
    let dir = std::env::var("SETTINGS_MESSAGES_PNG_DIR").map_or_else(
        |_| std::env::temp_dir().join("settings-messages"),
        std::path::PathBuf::from,
    );
    std::fs::create_dir_all(&dir).expect("output dir");
    let light = {
        let parts = aterm_types::scheme::builtin("GitHub Light")
            .expect("a builtin scheme")
            .to_theme_parts();
        aterm_render::Theme {
            fg: parts.fg,
            bg: parts.bg,
            cursor: parts.cursor,
            selection: parts.selection,
        }
    };
    let mut log = realistic_messages();
    let n = log.entries.len();
    for (k, entry) in log.entries.iter_mut().enumerate() {
        let days = match k * 10 / n.max(1) {
            0..=1 => 0,
            2..=3 => 1,
            4..=5 => 3,
            6..=8 => 12,
            _ => 400,
        };
        entry.at_unix_ms -= days * DAY;
        entry.retired_unix_ms = entry.retired_unix_ms.map(|t| t - days * DAY);
    }
    let past = log.entries[n / 2].id;
    for (ground, theme) in [("dark", aterm_render::Theme::default()), ("light", light)] {
        for (cols, width) in [(100, 774.0_f32), (60, 470.0)] {
            let at = (width, 612.0);
            let path = |name: &str| dir.join(format!("d-{name}-{ground}-{cols}.png"));
            let (mut runtime, instance, view) = setup_with_these_messages(log.clone());
            let _ = compile_settings_view(&runtime, instance, view, &view_cx_at(at.0, at.1));
            let limit = messages_view_state(&runtime, view)
                .result_page_limit
                .get()
                .expect("the render bounds the list");
            for (slug, top) in [("top", 0), ("middle", limit / 2 + 1), ("end", limit)] {
                {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.page_scroll = top;
                }
                let compiled = shoot_settings(
                    &runtime,
                    instance,
                    view,
                    at,
                    theme,
                    &path(&format!("log-{slug}")),
                );
                crate::logging::stderr_line!(
                    "{ground} {cols} {slug}: days {:?}",
                    message_days(&compiled)
                );
            }
            let (mut runtime, instance, view) = setup_with_these_messages(log.clone());
            messages_action(
                &mut runtime,
                instance,
                view,
                &format!("{MESSAGES_ACTION_PREFIX}filter/warn"),
            );
            shoot_settings(&runtime, instance, view, at, theme, &path("problems"));
            let (mut runtime, instance, view) = setup_with_these_messages(log.clone());
            select_message(&mut runtime, instance, view, past);
            shoot_settings(&runtime, instance, view, at, theme, &path("open-past"));
        }
    }
    crate::native_appearance::install_preferences(
        crate::native_appearance::AppearancePreferences {
            high_contrast: true,
            ..crate::native_appearance::current_preferences()
        },
    );
    let (runtime, instance, view) = setup_with_these_messages(log.clone());
    shoot_settings(
        &runtime,
        instance,
        view,
        (774.0, 612.0),
        aterm_render::Theme::default(),
        &dir.join("d-log-top-hc-dark-100.png"),
    );
}

/// VISUAL CAPTURE of Settings ▸ Messages (round 14): on the default dark
/// theme and GitHub Light, at a wide and a compact window — the empty
/// page; the realistic log ([`realistic_messages`]) as one scrolling list
/// — its top, middle and end, and one notch of the wheel (ruling 264); each
/// chip selected; a crash, a long toolchain failure and a strain record
/// expanded to their details; the "Explain heavy load" switch; and the
/// deep link's landing from Software Update (`settings/messages/show/update`).
/// Not part of a test run: `#[ignore]`d (it needs a real UI face).
///
/// ```sh
/// SETTINGS_MESSAGES_PNG_DIR=<dir> targo --unverified test -p aterm-gui --lib \
///     settings_messages_visual_capture -- --ignored --nocapture
/// ```
#[test]
#[ignore = "visual capture: needs a system UI face; run with --ignored"]
#[allow(
    clippy::too_many_lines,
    reason = "one list of page states, read top to bottom"
)]
fn settings_messages_visual_capture() {
    let dir = std::env::var("SETTINGS_MESSAGES_PNG_DIR").map_or_else(
        |_| std::env::temp_dir().join("settings-messages"),
        std::path::PathBuf::from,
    );
    std::fs::create_dir_all(&dir).expect("output dir");
    let light = {
        let parts = aterm_types::scheme::builtin("GitHub Light")
            .expect("a builtin scheme")
            .to_theme_parts();
        aterm_render::Theme {
            fg: parts.fg,
            bg: parts.bg,
            cursor: parts.cursor,
            selection: parts.selection,
        }
    };
    let log = realistic_messages();
    crate::logging::stderr_line!(
        "realistic log: {} entries, tags {:?}",
        log.entries.len(),
        log.tags
    );
    let find = |pred: &dyn Fn(&MessageView) -> bool, what: &str| {
        log.entries
            .iter()
            .find(|entry| pred(entry))
            .unwrap_or_else(|| panic!("the log holds {what}"))
            .id
    };
    let crash = find(&|e| e.tag == "crash", "a crash");
    let toolchain = find(
        &|e| e.tag == "toolchain" && e.severity == "warn" && e.detail.len() > 2,
        "a long toolchain failure",
    );
    let strain = find(
        &|e| e.tag == "system" && e.title.starts_with("Typing slowed by low memory"),
        "a strain record",
    );
    let empty = MessagesState {
        entries: Vec::new(),
        tags: Vec::new(),
        ..log.clone()
    };
    for (ground, theme) in [("dark", aterm_render::Theme::default()), ("light", light)] {
        for (size, width, height) in [("wide", 1_200.0_f32, 820.0_f32), ("compact", 568.0, 820.0)] {
            let at = (width, height);
            let path = |name: &str| dir.join(format!("{name}-{ground}-{size}.png"));
            // 01: the empty page.
            let (runtime, instance, view) = setup_with_these_messages(empty.clone());
            shoot_settings(&runtime, instance, view, at, theme, &path("s01-empty"));
            // 02: the log as ONE scrolling list (ruling 264): its top, its
            // middle and its end — the scroll thumb says where the view is.
            let (mut runtime, instance, view) = setup_with_these_messages(log.clone());
            let _ = compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
            let limit = messages_view_state(&runtime, view)
                .result_page_limit
                .get()
                .expect("the render bounds the list");
            for (slug, top) in [("top", 0), ("middle", limit / 2), ("end", limit)] {
                {
                    let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                        unreachable!();
                    };
                    state.page_scroll = top;
                }
                let compiled = shoot_settings(
                    &runtime,
                    instance,
                    view,
                    at,
                    theme,
                    &path(&format!("s02-log-{slug}")),
                );
                assert!(
                    compiled
                        .semantic(&UiKey::new("settings/messages/pagination"))
                        .is_none(),
                    "no pager ({size})"
                );
                if slug == "end" {
                    assert_eq!(
                        message_rows(&compiled).last(),
                        log.entries.last().map(|entry| entry.id).as_ref(),
                        "the end of the list is the oldest entry ({size})"
                    );
                }
            }
            // 02b: one notch of the wheel from the top: one entry on.
            let (mut runtime, instance, view) = setup_with_these_messages(log.clone());
            let _ = compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
            runtime
                .dispatch(instance, view, AppEvent::ScrollLines(1))
                .unwrap();
            shoot_settings(
                &runtime,
                instance,
                view,
                at,
                theme,
                &path("s02b-log-after-one-notch"),
            );
            // 03: each chip.
            let mut chips = vec![
                ("all".to_string(), "filter/all".to_string()),
                ("warn".to_string(), "filter/warn".to_string()),
            ];
            chips.extend(
                log.tags
                    .iter()
                    .map(|(tag, _)| (format!("tag-{tag}"), format!("filter/tag/{tag}"))),
            );
            for (slug, action) in chips {
                let (mut runtime, instance, view) = setup_with_these_messages(log.clone());
                messages_action(
                    &mut runtime,
                    instance,
                    view,
                    &format!("{MESSAGES_ACTION_PREFIX}{action}"),
                );
                shoot_settings(
                    &runtime,
                    instance,
                    view,
                    at,
                    theme,
                    &path(&format!("s03-chip-{slug}")),
                );
            }
            // 04: an entry expanded to its details, as the band's
            // `Details ›` lands on it (the deep link pages to it).
            for (slug, id) in [
                ("crash", crash),
                ("toolchain-failure", toolchain),
                ("strain-record", strain),
            ] {
                let (mut runtime, instance, view) = setup_with_these_messages(log.clone());
                // One render first, so the link lands as a person's does.
                compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
                select_message(&mut runtime, instance, view, id);
                shoot_settings(
                    &runtime,
                    instance,
                    view,
                    at,
                    theme,
                    &path(&format!("s04-expanded-{slug}")),
                );
            }
            // 05: the "Explain heavy load" switch — the top of the page at
            // every width (ruling 262), the compact page's tag pop-up open.
            let (mut runtime, instance, view) = setup_with_these_messages(log.clone());
            if size == "compact" {
                messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
            }
            let compiled = shoot_settings(
                &runtime,
                instance,
                view,
                at,
                theme,
                &path("s05-explain-heavy-load"),
            );
            assert!(
                compiled
                    .semantic(&UiKey::new(MESSAGES_EXPLAIN_LOAD))
                    .is_some(),
                "the switch is on the page ({size})"
            );
            // 06: the deep link from Software Update's "View Messages".
            let (mut runtime, instance, view) = setup_with_these_messages(log.clone());
            go_to_route(&mut runtime, instance, view, SettingsRoute::SoftwareUpdate);
            messages_action(&mut runtime, instance, view, MESSAGES_SHOW_UPDATE);
            assert_eq!(
                messages_view_state(&runtime, view).route,
                SettingsRoute::Messages
            );
            shoot_settings(
                &runtime,
                instance,
                view,
                at,
                theme,
                &path("s06-deep-link-update"),
            );
        }
    }
}

// ---------------------------------------------------------------------------
// Settings ▸ Messages: the keyboard, the scroll and the status line after an
// action, a publication or a scroll (ruling 441 (k)–(t)).
// ---------------------------------------------------------------------------

/// The Settings view's focused key, compiled at `cx`, and whether the page
/// shows it.
fn focus_on_page(
    runtime: &NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    cx: &ViewCx<'_>,
) -> (Option<UiKey>, bool) {
    let compiled = compile_settings_view(runtime, instance, view, cx);
    let focus = messages_view_state(runtime, view).common.last_focus.clone();
    let shown = focus
        .as_ref()
        .is_some_and(|key| compiled.semantic(key).is_some());
    (focus, shown)
}

/// Put the keyboard on `key`, as a click or Tab does.
fn focus_key(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    key: &str,
) {
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new(key.to_string()))),
        )
        .unwrap();
}

/// The Messages view's status line.
fn feedback_line(runtime: &NativeRuntime, view: crate::native_app::ViewId) -> Option<String> {
    messages_view_state(runtime, view).feedback.clone()
}

/// A publication of [`sample_messages`] at `now`, as the host's does.
fn publish_messages(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    now: u64,
    revision: u64,
) {
    let mut state = sample_messages();
    state.now_unix_ms = now;
    state.revision = revision;
    assert!(runtime.replace_settings_messages(state, revision));
    runtime
        .dispatch(instance, view, AppEvent::MessagesChanged { revision })
        .unwrap();
}

/// [`sample_messages`] with forty one-entry tags on top, so a compact page's
/// Tag pop-up holds more chip rows than the page has room for.
fn forty_tag_messages() -> MessagesState {
    script_tag_messages(40)
}

/// [`sample_messages`] with `n` one-entry tags on top (`script00`, …), as a
/// script that names its own tags posts them (ruling 267).
fn script_tag_messages(n: u64) -> MessagesState {
    let mut state = sample_messages();
    for k in 0..n {
        let tag = format!("script{k:02}");
        let mut entry = state.entries[3].clone();
        entry.id = 100 + k;
        entry.tag = tag.clone();
        state.entries.insert(0, entry);
        state.tags.push((tag, 1));
    }
    state
}

/// Ruling 441 (k), ruling 267 (the keyboard never leaves the page with no
/// focused node) and the choice picker's own close: a tag chosen from the
/// Tag pop-up with the keyboard puts focus back on the control that opened
/// it, never on a chip the closed pop-up took out of the tree.
#[test]
fn a_tag_chosen_from_the_pop_up_leaves_focus_on_its_button() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(474.0, 572.0);
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/40/title",
    );
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    focus_key(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    let chip = "settings/messages/filter/tag/crash";
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        compiled.semantic(&UiKey::new(chip)).is_some(),
        "premise: the pop-up shows the crash chip"
    );
    focus_key(&mut runtime, instance, view, chip);
    messages_action(&mut runtime, instance, view, chip);
    assert!(
        !messages_view_state(&runtime, view).messages_tag_menu,
        "premise: the choice closed the pop-up"
    );
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "the keyboard is on {focus:?}, which the page no longer shows"
    );
    assert_eq!(
        focus.as_ref().map(UiKey::as_str),
        Some(MESSAGES_TAG_MENU),
        "back on the control that opened the pop-up"
    );
}

/// Ruling 441 (l), ruling 264: on Messages `page_scroll` counts list stops,
/// bounded by the plan the Messages render records; a config publication
/// leaves the log where the reader is, never clamped to the Settings field
/// count.
#[test]
fn a_config_publication_leaves_a_deep_messages_scroll_where_it_is() {
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(full_ring_messages(), 8));
    let cx = view_cx();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(250))
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let deep = messages_view_state(&runtime, view).page_scroll;
    let fields = messages_view_state(&runtime, view).legacy.fields.len();
    assert!(
        deep > fields,
        "premise: scrolled past the field count ({deep} vs {fields})"
    );
    let rows = message_rows(&compiled);
    let mut service = VersionedConfigService::new(String::new()).unwrap();
    let snapshot = match service.patch(ConfigPatchRequest {
        base_revision: 1,
        edits: vec![ConfigKeyEdit {
            key: prefs::EDIT_THEME.to_string(),
            expected: ExpectedValue::Exact(None),
            value: Some("\"Nord\"".to_string()),
        }],
    }) {
        ConfigPatchResult::Applied { snapshot, .. } => snapshot,
        other => panic!("theme fixture patch failed: {other:?}"),
    };
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).page_scroll,
        deep,
        "an aterm.toml change moved the log"
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(message_rows(&compiled), rows, "the same entries shown");
}

/// Ruling 441 (m), ruling 264: the scroll moves on from the stop the reader
/// saw. A page action (an entry's Copy) handled before the next render must
/// not leave a following wheel event clamped to a limit of 0.
#[test]
fn a_scroll_after_a_page_action_moves_on_from_the_stop_shown() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(774.0, 612.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(3))
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let s = messages_view_state(&runtime, view).page_scroll;
    assert!(s > 0, "premise: the list scrolled");
    let seated = message_rows(&compiled)[0];
    messages_action(
        &mut runtime,
        instance,
        view,
        &format!("settings/messages/row/{seated}/copy"),
    );
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).page_scroll,
        s + 1,
        "the wheel after a Copy snapped the list"
    );
}

/// Ruling 441 (n), ruling 267 and `keep_message_focus_seated`'s doc: a
/// control the scroll unseats hands the keyboard to the first entry the
/// view shows (or, with none, the first header item still seated) — never
/// to an entry the view does not show. A compact page whose Tag pop-up
/// holds forty tags: past the switch, the header's chip rows leave no room
/// for a card, so the view seats no entry at all.
#[test]
fn focus_never_moves_to_an_unseated_entry_under_a_tall_header() {
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(forty_tag_messages(), 8));
    let cx = view_cx_at(474.0, 348.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    let switch = format!("settings/control/{}", prefs::EDIT_EXPLAIN_HEAVY_LOAD);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    focus_key(&mut runtime, instance, view, &switch);
    let (_, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(shown, "premise: the switch is on the page");
    for step in 0..12 {
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(1))
            .unwrap();
        let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
        assert!(
            shown,
            "step {step}: the keyboard is on {focus:?}, which the view does not show"
        );
    }
}

/// Ruling 441 (o), rulings 264 and 267: FOCUS NEVER SCROLLS AWAY. A focused
/// footer button of the open entry that the scroll unseats hands the
/// keyboard to what the view still shows, on the wide page and the compact
/// one.
#[test]
fn a_focused_footer_button_never_scrolls_away_with_its_entry() {
    for (w, h) in [(1_200.0, 820.0), (474.0, 572.0)] {
        let (mut runtime, instance, view) = setup_with_messages();
        let cx = view_cx_at(w, h);
        messages_action(
            &mut runtime,
            instance,
            view,
            "settings/messages/row/40/title",
        );
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        let copy = "settings/messages/row/40/copy";
        focus_key(&mut runtime, instance, view, copy);
        let (_, shown) = focus_on_page(&runtime, instance, view, &cx);
        assert!(
            shown,
            "{w} pt premise: the open entry's Copy is on the page"
        );
        let mut scrolled_away = false;
        for step in 0..6 {
            runtime
                .dispatch(instance, view, AppEvent::ScrollLines(1))
                .unwrap();
            let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
            scrolled_away |= messages_view_state(&runtime, view).page_scroll > 0;
            assert!(
                shown,
                "{w} pt step {step}: the keyboard is on {focus:?}, which the view does not show"
            );
        }
        assert!(scrolled_away, "{w} pt premise: the list scrolled");
    }
}

/// Ruling 441 (p): Escape closes the Tag pop-up, as `cancel_transient`
/// closes Settings' other pop-up (the choice picker), with focus back on
/// the control that opened it; it never throws the reader off the log.
#[test]
fn escape_closes_the_tag_pop_up_and_stays_on_the_log() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(474.0, 572.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/warn",
    );
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/40/title",
    );
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    focus_key(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    assert!(
        messages_view_state(&runtime, view).messages_tag_menu,
        "premise: open"
    );
    runtime
        .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Cancel))
        .unwrap();
    let state = messages_view_state(&runtime, view);
    assert_eq!(
        state.route,
        SettingsRoute::Messages,
        "Escape on the pop-up left the log"
    );
    assert!(!state.messages_tag_menu, "the pop-up closed");
    assert!(state.messages_filter.warn_only, "the filter stands");
    assert_eq!(state.messages_selected, Some(40), "the entry stays open");
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some(MESSAGES_TAG_MENU)
    );
}

/// Ruling 441 (p), its review: Escape closes the Tag pop-up with the
/// keyboard back on its button — a button the page SHOWS. On a compact page
/// the header scrolls with the log, and a pop-up whose chips scroll its own
/// button away left Escape's focus on a control the page no longer seats:
/// no ring, and the next Return fell through to the page's default action
/// (the failure (k) fixes for a chip's choice, which scrolls the list to
/// its top).
#[test]
fn escape_from_a_scrolled_tag_pop_up_seats_its_button() {
    let (mut runtime, instance, view) = setup_with_messages();
    assert!(runtime.replace_settings_messages(forty_tag_messages(), 8));
    let cx = view_cx_at(474.0, 348.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    focus_key(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
    let tag_menu = UiKey::new(MESSAGES_TAG_MENU);
    let mut away = false;
    for _ in 0..12 {
        runtime
            .dispatch(instance, view, AppEvent::ScrollLines(1))
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        if compiled.semantic(&tag_menu).is_none() {
            away = true;
            break;
        }
    }
    assert!(away, "premise: the pop-up's chips scrolled its button away");
    runtime
        .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Cancel))
        .unwrap();
    assert!(
        !messages_view_state(&runtime, view).messages_tag_menu,
        "premise: Escape closed the pop-up"
    );
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert_eq!(
        focus.as_ref().map(UiKey::as_str),
        Some(MESSAGES_TAG_MENU),
        "back on the button"
    );
    assert!(
        shown,
        "the keyboard is on {focus:?}, which the page does not show"
    );
}

/// Ruling 441 (p), its second review: the Tag pop-up takes Escape only
/// where the page draws it. Search Results and the compact category list
/// replace the page, and a pop-up left open under either took the first
/// Escape for a button the tree no longer held: the search stood, the list
/// stayed open, and the keyboard had no ring. Both close the pop-up as they
/// close the choice picker, and Escape does what it does there.
#[test]
fn a_tag_pop_up_under_search_or_the_category_list_takes_no_escape() {
    let cx = view_cx_at(474.0, 572.0);
    let open_pop_up = || {
        let (mut runtime, instance, view) = setup_with_messages();
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        focus_key(&mut runtime, instance, view, MESSAGES_TAG_MENU);
        messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
        assert!(
            messages_view_state(&runtime, view).messages_tag_menu,
            "premise: open"
        );
        (runtime, instance, view)
    };
    let escape = |runtime: &mut NativeRuntime,
                  instance: crate::native_app::AppInstanceId,
                  view: crate::native_app::ViewId| {
        runtime
            .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Cancel))
            .unwrap();
    };
    // Search Results over the page, reached as a person reaches them: the
    // search field, then typing.
    let (mut runtime, instance, view) = open_pop_up();
    focus_key(&mut runtime, instance, view, "settings/search");
    runtime
        .dispatch(instance, view, AppEvent::InsertText("font".to_string()))
        .unwrap();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    assert_eq!(
        messages_view_state(&runtime, view).search,
        "font",
        "premise: Search Results replace the page"
    );
    escape(&mut runtime, instance, view);
    let state = messages_view_state(&runtime, view);
    assert!(
        state.search.is_empty(),
        "Escape left the search standing: the pop-up it hid took it"
    );
    assert!(!state.messages_tag_menu, "the search closed the pop-up");
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "search: the keyboard is on {focus:?}, which the page does not show"
    );
    // The compact category list over the page.
    let (mut runtime, instance, view) = open_pop_up();
    messages_action(&mut runtime, instance, view, "settings/compact-navigation");
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    escape(&mut runtime, instance, view);
    let state = messages_view_state(&runtime, view);
    assert!(
        !state.compact_navigation,
        "Escape left the category list open: the pop-up it hid took it"
    );
    assert!(
        !state.messages_tag_menu,
        "the category list closed the pop-up"
    );
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "category list: the keyboard is on {focus:?}, which the page does not show"
    );
}

/// Ruling 441 (k) and (p), their second review: the pop-up's button is
/// the keyboard's place only where the page draws it. A compact page
/// widened under an open pop-up lays its tags out as chips, the pop-up
/// still open in the state and drawn nowhere: a chip chosen there keeps
/// the keyboard (it went to the absent button, and the next Return fell
/// through to the open entry's Primary), and Escape is not the hidden
/// pop-up's.
#[test]
fn a_pop_up_the_wider_page_does_not_draw_never_takes_the_keyboard() {
    let compact = view_cx_at(474.0, 572.0);
    let wide = view_cx_at(1_200.0, 820.0);
    let chip = "settings/messages/filter/tag/crash";
    let widened = || {
        let (mut runtime, instance, view) = setup_with_messages();
        let _ = compile_settings_view(&runtime, instance, view, &compact);
        focus_key(&mut runtime, instance, view, MESSAGES_TAG_MENU);
        messages_action(&mut runtime, instance, view, MESSAGES_TAG_MENU);
        let compiled = compile_settings_view(&runtime, instance, view, &wide);
        assert!(
            compiled.semantic(&UiKey::new(chip)).is_some()
                && compiled.semantic(&UiKey::new(MESSAGES_TAG_MENU)).is_none()
                && messages_view_state(&runtime, view).messages_tag_menu,
            "premise: the wide page lays its tags out as chips under an open pop-up"
        );
        focus_key(&mut runtime, instance, view, chip);
        (runtime, instance, view)
    };
    let (mut runtime, instance, view) = widened();
    messages_action(&mut runtime, instance, view, chip);
    let (focus, shown) = focus_on_page(&runtime, instance, view, &wide);
    assert_eq!(
        focus.as_ref().map(UiKey::as_str),
        Some(chip),
        "the chip chosen keeps the keyboard"
    );
    assert!(shown, "premise: the page shows the chip");
    let (mut runtime, instance, view) = widened();
    runtime
        .dispatch(instance, view, AppEvent::TextInput(TextInputEvent::Cancel))
        .unwrap();
    let state = messages_view_state(&runtime, view);
    assert_ne!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some(MESSAGES_TAG_MENU),
        "Escape put the keyboard on the button the page does not draw"
    );
    assert_eq!(
        state.route,
        SettingsRoute::Home,
        "Escape does what it does on a page with nothing open"
    );
}

/// Ruling 441 (q), rulings 267/268: only the line a Messages action set is
/// transient. A config patch's result that replaced it stands, as on every
/// other page.
#[test]
fn the_messages_clock_clears_only_the_line_it_set() {
    let (mut runtime, instance, view) = setup_with_messages();
    let effects = messages_action(&mut runtime, instance, view, "settings/messages/copy-all");
    let operation = effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::Clipboard { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("one clipboard effect");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ClipboardFinished {
                operation,
                outcome: ClipboardOutcome::Copied,
            },
        )
        .unwrap();
    let base = sample_messages().now_unix_ms;
    publish_messages(&mut runtime, instance, view, base, 8);
    assert_eq!(feedback_line(&runtime, view).as_deref(), Some("Copied"));
    let effects = runtime
        .dispatch(
            instance,
            view,
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(format!("settings/set/{}", prefs::EDIT_EXPLAIN_HEAVY_LOAD)),
                value: None,
            }),
        )
        .unwrap()
        .effects;
    let operation = effects
        .iter()
        .find_map(|effect| match effect {
            AppEffect::ConfigPatch { reply, .. } => Some(reply.operation),
            _ => None,
        })
        .expect("the switch's config patch");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::ConfigPatchFinished {
                operation,
                outcome: ConfigPatchOutcome::Rejected {
                    message: "x".to_string(),
                },
            },
        )
        .unwrap();
    assert_eq!(
        feedback_line(&runtime, view).as_deref(),
        Some("Explain heavy load was not saved: x"),
        "premise"
    );
    publish_messages(&mut runtime, instance, view, base + 6_000, 9);
    assert_eq!(
        feedback_line(&runtime, view).as_deref(),
        Some("Explain heavy load was not saved: x"),
        "the Copy's clock cleared the config patch's result"
    );
}

/// Ruling 441 (r), ruling 264: an entry opened low in the view is read
/// whole. A new record posted at the head of the list (the next publish)
/// must not push the entry just opened out of the view.
#[test]
fn a_new_record_never_pushes_the_open_entry_out_of_view() {
    let (mut runtime, instance, view) = setup_with_messages();
    let cx = view_cx_at(774.0, 612.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(2))
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    let last = *message_rows(&compiled).last().unwrap();
    messages_action(
        &mut runtime,
        instance,
        view,
        &format!("settings/messages/row/{last}/title"),
    );
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        message_rows(&compiled).contains(&last),
        "premise: the opened entry is shown"
    );
    post_newest(&mut runtime, instance, view, false);
    let compiled = compile_settings_view(&runtime, instance, view, &cx);
    assert!(
        message_rows(&compiled).contains(&last),
        "entry {last}, just opened, left the view when a record was posted: {:?}",
        message_rows(&compiled)
    );
}

/// The host's next publication of [`sample_messages`]: a config warning,
/// #41, posted at the head, and with `evict`, #1 — the oldest — gone from
/// the ring to make room for it.
fn post_newest(
    runtime: &mut NativeRuntime,
    instance: crate::native_app::AppInstanceId,
    view: crate::native_app::ViewId,
    evict: bool,
) {
    let mut state = sample_messages();
    let mut newest = state.entries[3].clone();
    newest.id = 41;
    newest.title = "config warning 41".to_string();
    state.entries.insert(0, newest);
    if evict {
        state.entries.retain(|entry| entry.id != 1);
    } else {
        for (tag, count) in &mut state.tags {
            if tag == "config" {
                *count += 1;
            }
        }
    }
    state.revision = 8;
    assert!(runtime.replace_settings_messages(state, 8));
    runtime
        .dispatch(instance, view, AppEvent::MessagesChanged { revision: 8 })
        .unwrap();
}

/// Ruling 441 (o) and (r), their second review: FOCUS NEVER MOVES AWAY
/// (ruling 267) under a publication either. A list at its newest entry
/// takes a new record at its top ((r) keeps no anchor there), so an entry
/// opened low in that view leaves it whole, its footer button with it; and
/// an entry the ring evicts leaves the list. Each left the keyboard on a
/// control the page no longer showed.
#[test]
fn a_publication_never_leaves_the_keyboard_on_an_entry_it_moved_away() {
    let cx = view_cx_at(774.0, 612.0);
    let shown_at_top = {
        let (runtime, instance, view) = setup_with_messages();
        message_rows(&compile_settings_view(&runtime, instance, view, &cx))
    };
    // Each entry the unscrolled view shows, opened where it stands and its
    // Copy focused; then a record is posted.
    let mut pushed = false;
    for id in shown_at_top {
        let (mut runtime, instance, view) = setup_with_messages();
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        messages_action(
            &mut runtime,
            instance,
            view,
            &format!("settings/messages/row/{id}/title"),
        );
        let copy = format!("settings/messages/row/{id}/copy");
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        if messages_view_state(&runtime, view).page_scroll != 0
            || compiled.semantic(&UiKey::new(copy.clone())).is_none()
        {
            // Opened by a scroll: (r)'s case, a test of its own.
            continue;
        }
        focus_key(&mut runtime, instance, view, &copy);
        post_newest(&mut runtime, instance, view, false);
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        pushed |= !message_rows(&compiled).contains(&id);
        let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
        assert!(
            shown,
            "entry {id}: the keyboard is on {focus:?}, which the view does not show"
        );
    }
    assert!(
        pushed,
        "premise: a record posted pushed an entry opened low in the view out of it"
    );
    // The oldest entry, open at the end of the list with its Copy focused,
    // evicted by the next record.
    let (mut runtime, instance, view) = setup_with_messages();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(250))
        .unwrap();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/1/title",
    );
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    let copy = "settings/messages/row/1/copy";
    focus_key(&mut runtime, instance, view, copy);
    let (_, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(shown, "premise: the oldest entry's Copy is on the page");
    post_newest(&mut runtime, instance, view, true);
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "eviction: the keyboard is on {focus:?}, which the view does not show"
    );
}

/// Ruling 441 (k) and (o), ruling 262's two lines: a publication never
/// leaves the keyboard on a Tag control it took off a wider page. New tags
/// a script names fold the chips into the `Tag: …` pop-up, so a focused
/// chip goes to the pop-up's button, as a choice in the pop-up puts it; a
/// ring that lets those tags go lets the chips out again and takes the
/// button away. A publication that keeps the chips keeps the chip focused.
#[test]
fn a_publication_that_folds_the_tag_chips_moves_the_keyboard_with_them() {
    let cx = view_cx_at(760.0, 820.0);
    let chip = "settings/messages/filter/tag/crash";
    let (mut runtime, instance, view) = setup_with_messages();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    focus_key(&mut runtime, instance, view, chip);
    messages_action(&mut runtime, instance, view, chip);
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown && focus.as_ref().map(UiKey::as_str) == Some(chip),
        "premise: the wide page shows the focused crash chip, focus {focus:?}"
    );
    // The control: a record posted under a tag the log has keeps the chips.
    post_newest(&mut runtime, instance, view, false);
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown && focus.as_ref().map(UiKey::as_str) == Some(chip),
        "a publication that kept the chips moved the keyboard to {focus:?}"
    );
    let publish = |runtime: &mut NativeRuntime, mut state: MessagesState, revision: u64| {
        state.revision = revision;
        assert!(runtime.replace_settings_messages(state, revision));
        runtime
            .dispatch(instance, view, AppEvent::MessagesChanged { revision })
            .unwrap();
        compile_settings_view(runtime, instance, view, &cx)
    };
    let compiled = publish(&mut runtime, script_tag_messages(2), 9);
    assert!(
        compiled.semantic(&UiKey::new(chip)).is_none()
            && compiled.semantic(&UiKey::new(MESSAGES_TAG_MENU)).is_some(),
        "premise: two new tags fold the chips into the Tag pop-up"
    );
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "folded: the keyboard is on {focus:?}, which the page no longer shows"
    );
    assert_eq!(
        focus.as_ref().map(UiKey::as_str),
        Some(MESSAGES_TAG_MENU),
        "folded: the chip's keyboard goes to the pop-up's button"
    );
    let compiled = publish(&mut runtime, sample_messages(), 10);
    assert!(
        compiled.semantic(&UiKey::new(chip)).is_some()
            && compiled.semantic(&UiKey::new(MESSAGES_TAG_MENU)).is_none(),
        "premise: without the new tags the chips are back"
    );
    let (focus, shown) = focus_on_page(&runtime, instance, view, &cx);
    assert!(
        shown,
        "unfolded: the keyboard is on {focus:?}, which the page no longer shows"
    );
}

/// Ruling 441 (s), ruling 267: "The status line an action on the Messages
/// page sets is transient: the next action on the page clears it". A
/// refused entry press's line is such a line.
#[test]
fn a_refused_entry_press_line_is_transient_too() {
    let (mut runtime, instance, view) = setup_with_messages();
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/row/9999/copy",
    );
    assert_eq!(
        feedback_line(&runtime, view).as_deref(),
        Some("That message is no longer in the log"),
        "premise"
    );
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/warn",
    );
    assert_eq!(
        feedback_line(&runtime, view),
        None,
        "the next action on the page did not clear it"
    );
}

/// Ruling 441 (t): the page says what happened, as its other outcomes do (a
/// refused `Open log` is `Could not open the log`): Open Log Folder's
/// `Opening the log folder…` is answered by the open's outcome, so a
/// failure can correct it, and the answer is transient like the page's
/// other lines.
#[cfg(target_os = "macos")]
#[test]
fn open_log_folder_waits_for_its_outcome() {
    let (mut runtime, instance, view) = setup_with_messages();
    let open = |runtime: &mut NativeRuntime| {
        let effects = messages_action(runtime, instance, view, MESSAGES_OPEN_FOLDER);
        effects
            .iter()
            .find_map(|effect| match effect {
                AppEffect::OpenLogFolder { reply } => Some(reply.operation),
                _ => None,
            })
            .expect("premise: the host is asked to open the folder")
    };
    let answer = |runtime: &mut NativeRuntime, operation, outcome| {
        runtime
            .dispatch(
                instance,
                view,
                AppEvent::ExternalOpenFinished { operation, outcome },
            )
            .unwrap();
    };
    let operation = open(&mut runtime);
    let state = messages_view_state(&runtime, view);
    assert_eq!(
        state.feedback.as_deref(),
        Some("Opening the log folder\u{2026}"),
        "premise"
    );
    assert!(
        !state.pending.is_empty(),
        "nothing waits for the open's outcome: a failure can never replace \
         `Opening the log folder\u{2026}`"
    );
    answer(
        &mut runtime,
        operation,
        ExternalOpenOutcome::Denied {
            message: "the log folder did not open".to_string(),
        },
    );
    let state = messages_view_state(&runtime, view);
    assert_eq!(
        state.feedback.as_deref(),
        Some("Couldn\u{2019}t open the log folder"),
        "a refused open is said"
    );
    assert_eq!(
        state.messages_feedback_clock(),
        Some(false),
        "the answer is transient: the next publish starts its clock"
    );
    let operation = open(&mut runtime);
    answer(&mut runtime, operation, ExternalOpenOutcome::Opened);
    assert_eq!(
        feedback_line(&runtime, view).as_deref(),
        Some("Opened the log folder")
    );
    messages_action(
        &mut runtime,
        instance,
        view,
        "settings/messages/filter/warn",
    );
    assert_eq!(
        feedback_line(&runtime, view),
        None,
        "the next action on the page clears it"
    );
}

/// The keys of every control a compiled screen draws, toolbar and rail aside.
fn page_controls(compiled: &crate::native_ui::CompiledUi) -> BTreeSet<String> {
    compiled
        .semantics
        .iter()
        .filter(|node| node.action.is_some())
        .map(|node| node.key.as_str().to_string())
        .filter(|key| {
            !key.starts_with("settings/nav")
                && !key.starts_with("settings/search")
                && !key.starts_with("settings/compact-navigation")
        })
        .collect()
}

/// EVERY CONTROL IS REACHED BY SCROLLING (the scroll-list ruling). For every
/// route at 584×348, 738×418 and 1074×684, every control the route draws in a
/// window of the same width tall enough to hold it all is on some screen of
/// its list, whole and inside the window; a screen that shows a preview also
/// shows a stop of the list under it; and the category sheet holds many
/// routes on a screen.
#[test]
fn every_route_reaches_every_control_by_scrolling_at_every_window_size() {
    for (width, height) in [(584.0, 348.0), (738.0, 418.0), (1_074.0, 684.0)] {
        for route in SettingsRoute::ALL {
            let (mut runtime, instance, view) = setup();
            assert!(runtime.replace_settings_packages(live_packages_state(None), 2));
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.navigate(route);
            }
            let tall = view_cx_at(width, 4_000.0);
            let expected = page_controls(&compile_settings_view(&runtime, instance, view, &tall));
            let cx = view_cx_at(width, height);
            let mut reached = BTreeSet::new();
            each_screen(&mut runtime, instance, view, &cx, |compiled, top| {
                let context = format!("{} {width}×{height} screen {top}", route.label());
                compiled
                    .validate_parity()
                    .unwrap_or_else(|error| panic!("{context}: {error:?}"));
                assert_all_hits_material_and_contained(compiled, &context);
                for hit in &compiled.hits {
                    let paint = compiled
                        .paint
                        .iter()
                        .find(|paint| paint.key == hit.key)
                        .unwrap_or_else(|| panic!("{context}: {:?} has no paint", hit.key));
                    assert_eq!(paint.rect, hit.rect, "{context}: {:?} is clipped", hit.key);
                }
                if compiled
                    .paint
                    .iter()
                    .any(|node| matches!(node.content, UiContent::SettingsPreview(_)))
                {
                    assert!(
                        compiled.semantics.iter().any(|node| {
                            node.parent
                                .as_ref()
                                .is_some_and(|parent| parent.as_str().ends_with("list"))
                        }),
                        "{context}: a screen is never only a preview"
                    );
                }
                reached.extend(page_controls(compiled));
            });
            let missing = expected.difference(&reached).collect::<Vec<_>>();
            assert!(
                missing.is_empty(),
                "{} {width}×{height}: never reached {missing:?}",
                route.label()
            );
        }

        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.compact_navigation = true;
        }
        let compiled = compile_settings_view(&runtime, instance, view, &view_cx_at(width, height));
        let routes = compiled
            .semantics
            .iter()
            .filter(|node| node.key.as_str().starts_with("settings/categories/"))
            .filter(|node| node.action.is_some())
            .count();
        if SettingsWidth::for_viewport(width) == SettingsWidth::Compact {
            assert!(
                routes >= 6,
                "the {width}×{height} category sheet holds {routes} routes on a screen"
            );
        }
    }
}

/// THE PINNED PREVIEW STILL PREVIEWS. A typography specimen paints whole
/// rows only, so where a screen has room for one row beside the list it
/// keeps that row (at 48pt the Text & Fonts preview showed its header and no
/// text); and a screen of the list never shows one stop where the preview,
/// yielding to its floor, would have made room for two.
#[test]
fn the_pinned_preview_keeps_a_specimen_row_and_yields_for_a_second_stop() {
    for (route, width, height) in [
        (SettingsRoute::TextFonts, 584.0, 348.0),
        (SettingsRoute::TextFonts, 1_074.0, 684.0),
        (SettingsRoute::CursorMotion, 724.0, 488.0),
        (SettingsRoute::CursorMotion, 738.0, 418.0),
        (SettingsRoute::Appearance, 738.0, 418.0),
        (SettingsRoute::Appearance, 584.0, 348.0),
    ] {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(route);
        }
        let cx = view_cx_at(width, height);
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        let limit = messages_view_state(&runtime, view)
            .scroll_plan()
            .expect("a measured list")
            .limit();
        for top in 0..=limit {
            {
                let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                    unreachable!();
                };
                state.page_scroll = top;
            }
            let compiled = compile_settings_view(&runtime, instance, view, &cx);
            let context = format!("{} {width}×{height} screen {top}", route.label());
            let (floor, preview) = compiled
                .paint
                .iter()
                .find_map(|node| match &node.content {
                    UiContent::SettingsPreview(spec) => {
                        Some((spec.minimum_height(48.0), node.rect.height))
                    }
                    _ => None,
                })
                .unwrap_or_else(|| panic!("{context}: the preview is pinned"));
            assert!(
                preview + 0.01 >= floor,
                "{context}: the {preview}pt preview is under its {floor}pt floor"
            );
            let (plan, shown) = messages_view_state(&runtime, view)
                .scroll_shown()
                .expect("a measured list");
            assert!(
                shown.len() >= 2
                    || shown.end == plan.len()
                    || plan.span(shown.start..shown.start + 2)
                        > plan.room() + (preview - floor) + 0.01,
                "{context}: one stop where the preview could yield for two"
            );
        }
    }
}

/// UP AND DOWN WALK THE PAGE (ruling 264): from a control in the list the
/// keyboard moves to the next or the previous one wherever it is, and the
/// list follows it; past the ends it stays put; with the keyboard outside the
/// list, Down scrolls a row.
#[test]
fn up_and_down_walk_the_page_controls_and_the_list_follows() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::Appearance);
    }
    let cx = view_cx_at(738.0, 418.0);
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    let controls: Vec<UiKey> = messages_view_state(&runtime, view)
        .scroll_plan()
        .expect("a measured list")
        .controls()
        .map(|(_, key)| key.clone())
        .collect();
    assert!(controls.len() > 4, "{controls:?}");
    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(controls[0].clone())),
        )
        .unwrap();
    let focus =
        |runtime: &NativeRuntime| messages_view_state(runtime, view).common.last_focus.clone();
    for expected in controls.iter().skip(1) {
        runtime
            .dispatch(instance, view, AppEvent::StepFocus(1))
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert_eq!(focus(&runtime).as_ref(), Some(expected));
        assert!(
            compiled.semantic(expected).is_some(),
            "the list follows the keyboard to {expected:?}"
        );
    }
    runtime
        .dispatch(instance, view, AppEvent::StepFocus(1))
        .unwrap();
    assert_eq!(
        focus(&runtime).as_ref(),
        controls.last(),
        "Down past the end stays"
    );
    for expected in controls.iter().rev().skip(1) {
        runtime
            .dispatch(instance, view, AppEvent::StepFocus(-1))
            .unwrap();
        let compiled = compile_settings_view(&runtime, instance, view, &cx);
        assert_eq!(focus(&runtime).as_ref(), Some(expected));
        assert!(compiled.semantic(expected).is_some());
    }

    runtime
        .dispatch(
            instance,
            view,
            AppEvent::FocusChanged(Some(UiKey::new("settings/search"))),
        )
        .unwrap();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(-10_000))
        .unwrap();
    let _ = compile_settings_view(&runtime, instance, view, &cx);
    runtime
        .dispatch(instance, view, AppEvent::StepFocus(1))
        .unwrap();
    assert_eq!(
        messages_view_state(&runtime, view).page_scroll,
        1,
        "Down with the keyboard outside the list scrolls a row"
    );
}

/// A SAVE NEVER MOVES THE ROW UNDER THE POINTER. On a compact window the
/// status bar a change brings up takes room from the list, and the list keeps
/// the control the person just used in view — reached by the keyboard, or
/// changed by an action alone; a wider page keeps the bar's room, so the list
/// does not move at all.
#[test]
fn the_status_bar_never_scrolls_the_edited_row_away() {
    for (width, height, by_focus) in [
        (724.0, 488.0, true),
        (724.0, 488.0, false),
        (1_074.0, 684.0, true),
    ] {
        let (mut runtime, instance, view) = setup();
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.navigate(SettingsRoute::CursorMotion);
        }
        let cx = view_cx_at(width, height);
        // The controls of the stops a screen shows: the peek under them runs
        // on into the room the bar takes, so a bar that comes takes only peek.
        let screen = |runtime: &NativeRuntime| {
            let (plan, shown) = messages_view_state(runtime, view)
                .scroll_shown()
                .expect("a measured list");
            plan.controls()
                .filter(|(stop, _)| shown.contains(stop))
                .map(|(_, key)| key.as_str().to_string())
                .collect::<BTreeSet<_>>()
        };
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        let before = screen(&runtime);
        let (plan, shown) = messages_view_state(&runtime, view)
            .scroll_shown()
            .expect("a measured list");
        // The last control the first screen shows.
        let edited = plan
            .controls()
            .filter(|(stop, _)| shown.contains(stop))
            .map(|(_, key)| key.clone())
            .last()
            .expect("a control on the first screen");
        let event = if by_focus {
            AppEvent::FocusChanged(Some(edited.clone()))
        } else {
            AppEvent::Action(ActionInvocation {
                id: ActionId::new(
                    edited
                        .as_str()
                        .replace("settings/control/", "settings/set/"),
                ),
                value: None,
            })
        };
        runtime.dispatch(instance, view, event).unwrap();
        let _ = compile_settings_view(&runtime, instance, view, &cx);
        {
            let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
                unreachable!();
            };
            state.feedback = Some("Applied".to_string());
            state.last_undo = Some(UndoOffer::showing(1, "Applied"));
        }
        let after = compile_settings_view(&runtime, instance, view, &cx);
        assert!(
            after.semantic(&UiKey::new("settings/status")).is_some(),
            "{width}×{height}: the status bar is up"
        );
        assert!(
            after.semantic(&edited).is_some(),
            "{width}×{height}: {edited:?} stays in view"
        );
        if SettingsWidth::for_viewport(width) != SettingsWidth::Compact {
            assert_eq!(
                screen(&runtime),
                before,
                "{width}×{height}: the list keeps the bar's room and does not move"
            );
        }
    }
}

/// A GROWN WINDOW RE-CLAMPS THE LIST: scrolled to its end in a small window,
/// the list in a taller one starts where its last screen is full, and the
/// next event adopts that scroll.
#[test]
fn a_grown_window_reclamps_the_scroll_to_a_full_last_screen() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!();
        };
        state.navigate(SettingsRoute::TextFonts);
        state.page_scroll = usize::MAX;
    }
    let small = view_cx_at(584.0, 348.0);
    let _ = compile_settings_view(&runtime, instance, view, &small);
    let small_limit = messages_view_state(&runtime, view)
        .scroll_plan()
        .expect("a measured list")
        .limit();
    assert!(small_limit > 0);
    let tall = view_cx_at(1_074.0, 1_400.0);
    let compiled = compile_settings_view(&runtime, instance, view, &tall);
    let (plan, shown) = messages_view_state(&runtime, view)
        .scroll_shown()
        .expect("a measured list");
    assert_eq!(
        shown.end,
        plan.len(),
        "the grown window shows the list's end"
    );
    assert!(
        shown.start == 0 || plan.view(shown.start - 1).end < plan.len(),
        "the last screen is full: {shown:?} of {}",
        plan.len()
    );
    assert!(compiled.semantic(&UiKey::new("settings/list")).is_some());
    runtime
        .dispatch(instance, view, AppEvent::ScrollLines(0))
        .unwrap();
    assert_eq!(messages_view_state(&runtime, view).page_scroll, shown.start);
}

/// Serious Mode hides the playful rainbow on Top Settings, so it hides the
/// rainbow wash behind every Settings page too: the page that announces it is
/// hiding playful effects no longer sits on one.
#[test]
fn serious_mode_paints_the_settings_canvas_plain() {
    let (runtime, instance, view) = setup();
    for (serious, surface) in [(false, StyleRef::Hero), (true, StyleRef::Plain)] {
        let mut cx = view_cx();
        cx.motion.serious = serious;
        let tree = runtime.render(instance, view, &cx).unwrap();
        let UiContent::Group(spec) = &tree.root.content else {
            panic!("the Settings root is a group");
        };
        assert_eq!(spec.role, SemanticRole::Application);
        assert_eq!(spec.style, surface, "serious mode {serious}");
    }
}

fn action(id: &str, value: Option<SemanticInput>) -> AppEvent {
    AppEvent::Action(ActionInvocation {
        id: ActionId::new(id),
        value,
    })
}

fn patch_edits(outcome: &crate::native_app::DispatchOutcome) -> Vec<(String, Option<String>)> {
    outcome
        .effects
        .iter()
        .filter_map(|effect| match effect {
            AppEffect::ConfigPatch { patch, .. } => Some(patch),
            _ => None,
        })
        .flat_map(|patch| patch.edits.iter())
        .map(|edit| (edit.key.clone(), edit.value.clone()))
        .collect()
}

/// Arriving on the Wallpaper page opens nothing: on macOS a visit with no
/// wallpaper set used to raise the modal file picker, from the sidebar and
/// from `open app settings /wallpaper` alike. Only the button opens it.
#[test]
fn visiting_the_wallpaper_page_opens_no_picker() {
    let (mut runtime, instance, view) = setup();
    let visit = runtime
        .dispatch(instance, view, action("settings/route/wallpaper", None))
        .unwrap();
    assert!(
        !visit
            .effects
            .iter()
            .any(|effect| matches!(effect, AppEffect::ChooseWallpaperImage)),
        "a visit opens no picker"
    );
    let press = runtime
        .dispatch(instance, view, action("settings/wallpaper/choose", None))
        .unwrap();
    assert!(
        press
            .effects
            .iter()
            .any(|effect| matches!(effect, AppEffect::ChooseWallpaperImage)),
        "the button does"
    );
}

/// The Wallpaper page names the file, says on its own line why it did not
/// load, and carries the dim and text tint rows that used to be Manual-only.
#[test]
fn the_wallpaper_page_names_the_file_and_the_failure_and_owns_dim_and_tint() {
    let mut state = SettingsViewState::new(&Config::default());
    state.navigate(SettingsRoute::Wallpaper);
    let path = "/Users//someone/Library/Mobile Documents/com~apple~CloudDocs/Pictures/notes.txt";
    state
        .raw_values
        .insert(prefs::EDIT_WALLPAPER.to_string(), path.to_string());
    state.assets = std::sync::Arc::new(crate::app_config::ConfigAssetCatalog {
        wallpaper: crate::app_config::WallpaperAsset::Invalid {
            source_id: path.into(),
            bounded_reason: "not a decodable image".into(),
        },
        ..crate::app_config::ConfigAssetCatalog::default()
    });
    for (width, height) in [(744.0_f32, 420.0_f32), (1_200.0, 820.0)] {
        let compiled = settings_route_at(&state, &view_cx_at(width, height));
        let context = format!("Wallpaper at {width}×{height}");
        let current = compiled
            .semantic(&UiKey::new("settings/wallpaper/current"))
            .unwrap_or_else(|| panic!("{context}: the status"));
        assert!(current.label.contains(path), "{context}: {}", current.label);
        assert_eq!(
            painted_text(&compiled, "settings/wallpaper/current/visual"),
            "notes.txt",
            "{context}: the file by its name"
        );
        let problem = painted_copy_lines(&compiled, "settings/wallpaper/problem").join(" ");
        assert_eq!(
            problem, "Couldn't load this image: not a decodable image",
            "{context}"
        );
        for key in ["wallpaper_dim", "wallpaper_text_tint"] {
            assert!(
                compiled
                    .semantic(&UiKey::new(format!("settings/control/{key}")))
                    .is_some(),
                "{context}: {key} has a row"
            );
            // An image that did not load draws nothing to dim or tint.
            let label = compiled
                .semantic(&UiKey::new(format!("settings/label/{key}")))
                .map(|node| node.label.clone())
                .unwrap_or_default();
            assert!(
                label.contains("image didn't load"),
                "{context}: {key} says why it does nothing: {label}"
            );
        }
        assert!(
            compiled
                .paint_audit_lines()
                .iter()
                .all(|line| !line.contains("overflow=true")),
            "{context}: nothing is cut off\n{}",
            compiled.paint_audit_lines().join("\n")
        );
    }
    // Negative control: a loaded image leaves the rows active.
    state.assets = std::sync::Arc::new(crate::app_config::ConfigAssetCatalog {
        wallpaper: crate::app_config::WallpaperAsset::Ready {
            source_id: path.into(),
            w: 1,
            h: 1,
            rgba: std::sync::Arc::from(vec![0_u8; 4]),
            fp: 1,
        },
        ..crate::app_config::ConfigAssetCatalog::default()
    });
    let compiled = settings_route_at(&state, &view_cx_at(1_200.0, 820.0));
    for key in ["wallpaper_dim", "wallpaper_text_tint"] {
        let label = compiled
            .semantic(&UiKey::new(format!("settings/label/{key}")))
            .map(|node| node.label.clone())
            .unwrap_or_default();
        assert!(!label.contains("Inactive"), "{key}: {label}");
    }
    // The rows live on the Wallpaper page, not the Appearance page.
    assert!(!settings_field_is_visible(
        prefs::EDIT_WALLPAPER_DIM,
        false,
        false
    ));
    assert!(settings_field_is_visible(
        prefs::EDIT_WALLPAPER_DIM,
        false,
        true
    ));
}

fn painted_text(compiled: &crate::native_ui::CompiledUi, key: &str) -> String {
    compiled
        .paint
        .iter()
        .find_map(|node| match &node.content {
            UiContent::Text(spec) if node.key.as_str() == key => Some(spec.text.clone()),
            _ => None,
        })
        .unwrap_or_else(|| panic!("{key} paints text"))
}

/// THE WINDOW PAGE'S TAB COLOR ROW SHOWS THE COLOR IT NAMES: the row that
/// goes to Tab Color wears the chip the hex field wears, at the regular and
/// the compact widths, and an unset color wears none (the system pill has no
/// one colour that would be true).
#[test]
fn the_window_tab_color_row_shows_the_color_it_names() {
    use crate::widget::DrawPrim;
    let orange = [0xE6, 0x7A, 0x00];
    let key = format!("settings/control/{}", prefs::EDIT_ACTIVE_TAB_COLOR);
    for (width, height) in [(1_200.0_f32, 820.0_f32), (474.0, 1_400.0)] {
        for source in ["active_tab_color = \"#E67A00\"\n", ""] {
            let snapshot = VersionedConfigService::new(source.to_string())
                .unwrap()
                .snapshot();
            let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
            state.navigate(SettingsRoute::WindowTabs);
            let compiled = settings_route_at(&state, &view_cx_at(width, height));
            let at = format!("{width}x{height} {source:?}");
            let node = compiled
                .paint
                .iter()
                .find(|node| node.key.as_str() == key)
                .unwrap_or_else(|| panic!("{at}: the row's control is painted"));
            let UiContent::Button(button) = &node.content else {
                panic!("{at}: the Window row is a button: {:?}", node.content);
            };
            let hit = compiled
                .hits
                .iter()
                .find(|hit| hit.key.as_str() == key)
                .unwrap_or_else(|| panic!("{at}: the row is live"));
            assert_eq!(hit.action.as_str(), "settings/route/tab-color", "{at}");
            let set = !source.is_empty();
            assert_eq!(button.spec.chip, set.then_some(orange), "{at}");
            let prims = compiled.tray(aterm_render::Theme::default(), 13.0).prims;
            let rect = node.rect;
            let painted = prims.iter().any(|prim| {
                matches!(prim, DrawPrim::Panel { x, y, w, h, fill, .. }
                    if fill[..3] == orange
                        && *x >= rect.x && *y >= rect.y
                        && x + w <= rect.right() && y + h <= rect.bottom())
            });
            assert_eq!(
                painted, set,
                "{at}: the chip is painted in the row's control"
            );
        }
    }
}

/// At the shipped default size (and at 80×24) the wheel, Brightness and
/// the hex field share one screen: before any color is set, and after a
/// pick, with the Undo bar taking its row of the page.
#[test]
fn tab_color_shows_the_wheel_and_what_it_sets_on_one_screen() {
    // The shipped 102x29 window, and 80x24's live viewport (584x348), where a
    // pick's Undo bar used to switch the page to its stacked layout and
    // scroll the wheel away.
    for (width, height) in [(744.0_f32, 420.0_f32), (584.0, 348.0)] {
        for source in ["", "active_tab_color = \"#E67A00\"\n"] {
            let snapshot = VersionedConfigService::new(source.to_string())
                .unwrap()
                .snapshot();
            let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
            state.navigate(SettingsRoute::TabColor);
            if !source.is_empty() {
                let status = "Selected tab color set to #E67A00";
                state.feedback = Some(status.to_string());
                state.last_undo = Some(UndoOffer::showing(1, status));
            }
            let compiled = settings_route_at(&state, &view_cx_at(width, height));
            let context = format!("{width}×{height} with {source:?}");
            let list = compiled
                .semantic(&UiKey::new("settings/tab-color/list"))
                .unwrap_or_else(|| panic!("{context}: the list"))
                .rect;
            for key in [
                "settings/tab-color/wheel",
                "settings/tab-color/brightness",
                "settings/control/active_tab_color",
            ] {
                let rect = compiled
                    .semantic(&UiKey::new(key))
                    .unwrap_or_else(|| panic!("{context}: {key} is on the first screen"))
                    .rect;
                assert!(
                    rect.y >= list.y - 0.5 && rect.bottom() <= list.bottom() + 0.5,
                    "{context}: {key} lies whole inside the list: {rect:?} in {list:?}"
                );
            }
        }
    }
    // THE WHEEL STAYS UNDER THE POINTER: on one config, the Undo bar a pick
    // brings up moves and resizes nothing of the picker (80x24 used to open
    // with a 179pt wheel that became a 161pt one 35pt higher on the first
    // pick, so a second click at the same spot chose another color).
    for (width, height) in [(744.0_f32, 420.0_f32), (584.0, 348.0)] {
        let snapshot = VersionedConfigService::new("active_tab_color = \"#33CC66\"\n".to_string())
            .unwrap()
            .snapshot();
        let mut state = SettingsViewState::from_snapshot(&snapshot).unwrap();
        state.navigate(SettingsRoute::TabColor);
        let rects = |state: &SettingsViewState| {
            let compiled = settings_route_at(state, &view_cx_at(width, height));
            [
                "settings/tab-color/wheel",
                "settings/tab-color/brightness",
                "settings/control/active_tab_color",
            ]
            .map(|key| {
                compiled
                    .semantic(&UiKey::new(key))
                    .unwrap_or_else(|| panic!("{width}×{height}: {key}"))
                    .rect
            })
        };
        let before = rects(&state);
        let status = "Selected tab color set to #33CC66";
        state.feedback = Some(status.to_string());
        state.last_undo = Some(UndoOffer::showing(1, status));
        assert_eq!(
            rects(&state),
            before,
            "{width}×{height}: the Undo bar moves nothing of the picker"
        );
    }
    // The default reads in words, never a config word.
    let state = SettingsViewState::new(&Config::default());
    let field = state.field_by_key(prefs::EDIT_ACTIVE_TAB_COLOR).unwrap();
    assert_eq!(field.placeholder, "Automatic (default)");
    assert_eq!(
        default_value_label(prefs::EDIT_ACTIVE_TAB_COLOR),
        Some("Automatic")
    );
}

/// Tab lands on the wheel as on any control: it reports focus, and its
/// painter draws the focus ring.
#[test]
fn the_tab_color_wheel_reports_and_shows_keyboard_focus() {
    let mut state = SettingsViewState::new(&Config::default());
    state.navigate(SettingsRoute::TabColor);
    let cx = view_cx_at(1_200.0, 820.0);
    let mut tree = settings_tree(
        &state,
        &UpdateState::from_status(1, "0.1.0", None, false).projection(),
        &PackagesState::unobserved().projection(),
        &MessagesState::empty(),
        &HarnessState::unobserved().projection(),
        &cx,
    );
    let wheel = UiKey::new("settings/tab-color/wheel");
    tree.apply_interaction(Some(&wheel), None, None, true);
    let compiled = tree.compile(cx.viewport).unwrap();
    let semantic = compiled.semantic(&wheel).expect("the wheel");
    assert!(
        semantic
            .state
            .is_some_and(|state| state.focused && state.focus_visible),
        "{:?}",
        semantic.state
    );
    let painted = compiled
        .paint
        .iter()
        .find(|node| node.key == wheel)
        .expect("the wheel paints");
    assert!(
        matches!(&painted.content, UiContent::Custom(spec) if spec.focus_visible),
        "the painter is told to ring it"
    );
    // Elsewhere, no ring.
    let compiled = settings_route_at(&state, &cx);
    assert!(
        compiled
            .semantic(&wheel)
            .and_then(|node| node.state)
            .is_some_and(|state| !state.focused)
    );
}

/// The Tab Color page is usable without a pointer: the wheel takes a hex
/// value, the ordinary hex row under it writes the key, brightness darkens
/// the chosen color, and Reset is offered only when a color is set.
#[test]
fn tab_color_takes_hex_text_brightness_and_resets_only_a_set_color() {
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(instance, view, action("settings/route/tab-color", None))
        .unwrap();
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx());
    let wheel = compiled
        .semantic(&UiKey::new("settings/tab-color/wheel"))
        .expect("the wheel");
    assert!(
        matches!(wheel.value, SemanticValue::Text(_)),
        "the wheel accepts a value"
    );
    assert!(wheel.state.is_some_and(|state| state.enabled));
    let row = compiled
        .semantic(&UiKey::new("settings/control/active_tab_color"))
        .expect("the hex row");
    assert_eq!(row.role, SemanticRole::TextField);
    assert!(
        compiled
            .semantic(&UiKey::new("settings/tab-color/brightness"))
            .and_then(|node| node.state)
            .is_some_and(|state| !state.enabled),
        "brightness waits for a color"
    );
    assert!(
        compiled
            .semantic(&UiKey::new("settings/reset/active_tab_color"))
            .is_none(),
        "the row offers Reset only once a color is written"
    );

    let set = runtime
        .dispatch(
            instance,
            view,
            action(
                "settings/set/active_tab_color",
                Some(SemanticInput::Text("#FF8800".to_string())),
            ),
        )
        .unwrap();
    assert_eq!(
        patch_edits(&set),
        vec![("active_tab_color".to_string(), Some("#FF8800".to_string()))]
    );

    // Brightness keeps the hue: #FF8800 at half brightness.
    let snapshot = VersionedConfigService::new(String::new())
        .unwrap()
        .replace_external("active_tab_color = \"#FF8800\"\n".to_string())
        .unwrap();
    let (mut runtime, instance, view) = setup();
    runtime
        .dispatch(instance, view, AppEvent::ConfigChanged(snapshot))
        .unwrap();
    let darker = runtime
        .dispatch(
            instance,
            view,
            action(
                "settings/tab-color/brightness",
                Some(SemanticInput::Number(0.5)),
            ),
        )
        .unwrap();
    assert_eq!(
        patch_edits(&darker),
        vec![("active_tab_color".to_string(), Some("#804400".to_string()))]
    );
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    assert_eq!(
        state.common.last_focus.as_ref().map(UiKey::as_str),
        Some("settings/tab-color/brightness")
    );
}

/// A color that is not hex stays where it was typed, marked, with the reason
/// in words; it never reaches the config file to be refused there.
#[test]
fn an_invalid_color_keeps_its_draft_and_says_why() {
    let (mut runtime, instance, view) = setup();
    {
        let Some(AppViewState::Settings(state)) = runtime.view_state_mut(view) else {
            unreachable!()
        };
        state.navigate(SettingsRoute::Appearance);
    }
    let outcome = runtime
        .dispatch(
            instance,
            view,
            action(
                "settings/set/foreground",
                Some(SemanticInput::Text("orange".to_string())),
            ),
        )
        .unwrap();
    assert!(patch_edits(&outcome).is_empty(), "nothing is written");
    let Some(AppViewState::Settings(state)) = runtime.view_state(view) else {
        panic!("Settings view")
    };
    // The status says only that it was not saved (so it offers no Undo);
    // the reason is under the row.
    assert_eq!(state.feedback.as_deref(), Some("Foreground was not saved"));
    assert_eq!(
        state
            .field_errors
            .get(prefs::EDIT_FOREGROUND)
            .map(String::as_str),
        Some("Foreground needs a hex color like #D0D0D0; \"orange\" was not saved")
    );
    assert_eq!(
        state
            .field_inputs
            .get(prefs::EDIT_FOREGROUND)
            .map(|input| input.value()),
        Some("orange")
    );
    let compiled = compile_settings_view(&runtime, instance, view, &view_cx());
    assert!(
        compiled
            .semantic(&UiKey::new("settings/control/foreground"))
            .and_then(|node| node.state)
            .is_some_and(|state| state.invalid),
        "the field is marked"
    );
    let label = &compiled
        .semantic(&UiKey::new("settings/label/foreground"))
        .unwrap()
        .label;
    assert!(
        !label.contains("Runtime fallback"),
        "the saved value is not the one at fault: {label}"
    );
}

